/**
 * agent-chain — Cortex Sequential Pipeline Orchestrator
 *
 * Lee los pipelines definidos en .pi/agents/agent-chain.yaml y los ejecuta
 * como cadenas secuenciales: el output de cada paso se convierte en $INPUT
 * del siguiente. $ORIGINAL siempre contiene el prompt inicial del usuario.
 *
 * Pipelines disponibles en Cortex:
 *   - sddwork  → Ciclo completo: sync → SDDwork → security → test → docs
 *   - hotfix   → Fast Track directo: SDDwork → docs
 *   - refactor → Análisis profundo: sync → explorer → implementer → docs
 *
 * Comandos:
 *   /chain        → selector interactivo de pipeline
 *   /chain-list   → lista todos los pipelines disponibles
 *
 * Uso: pi -e .pi/extensions/agent-chain.ts
 *
 * Basado en disler/pi-vs-claude-code agent-chain.ts, adaptado para Cortex.
 */

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { Text } from "@mariozechner/pi-tui";
import { readFileSync, existsSync, readdirSync, mkdirSync } from "fs";
import { join } from "path";
import { spawn } from "child_process";

// ── Types ──────────────────────────────────────────────────────────────────

interface ChainStep {
  agent: string;
  prompt: string;
}

interface ChainDef {
  key: string;
  description: string;
  steps: ChainStep[];
}

interface AgentDef {
  name: string;
  description: string;
  tools: string;
  systemPrompt: string;
}

interface StepState {
  agent: string;
  status: "pending" | "running" | "done" | "error";
  elapsed: number;
  lastLine: string;
}

// ── Parsers ────────────────────────────────────────────────────────────────

function parseAgentFile(filePath: string): AgentDef | null {
  try {
    const raw = readFileSync(filePath, "utf-8");
    const match = raw.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]*)$/);
    if (!match) return null;

    const fm: Record<string, string> = {};
    for (const line of match[1].split("\n")) {
      const idx = line.indexOf(":");
      if (idx > 0) fm[line.slice(0, idx).trim()] = line.slice(idx + 1).trim();
    }

    if (!fm.name) return null;
    return {
      name: fm.name,
      description: fm.description || "",
      tools: fm.tools || "read,grep,find,ls,bash",
      systemPrompt: match[2].trim(),
    };
  } catch {
    return null;
  }
}

function scanAgents(cwd: string): Map<string, AgentDef> {
  const agentsDir = join(cwd, ".pi", "agents");
  const agents = new Map<string, AgentDef>();
  if (!existsSync(agentsDir)) return agents;

  try {
    for (const file of readdirSync(agentsDir)) {
      if (!file.endsWith(".md")) continue;
      const def = parseAgentFile(join(agentsDir, file));
      if (def) agents.set(def.name.toLowerCase(), def);
    }
  } catch {}
  return agents;
}

/**
 * Parser manual de agent-chain.yaml (formato Cortex).
 * Soporta la estructura:
 *   chains:
 *     sddwork:
 *       description: "..."
 *       steps:
 *         - agent: cortex-sync
 *           prompt: |
 *             ...
 */
function parseChainYaml(raw: string): ChainDef[] {
  const chains: ChainDef[] = [];
  const lines = raw.split("\n");
  let i = 0;

  // Salta hasta "chains:"
  while (i < lines.length && !lines[i].match(/^chains:\s*$/)) i++;
  i++; // salta la línea "chains:"

  while (i < lines.length) {
    // Chain key: dos espacios + nombre + ":"
    const chainMatch = lines[i].match(/^  (\S+):\s*$/);
    if (!chainMatch) { i++; continue; }

    const chain: ChainDef = { key: chainMatch[1], description: "", steps: [] };
    chains.push(chain);
    i++;

    // Parsea description y steps dentro del chain
    while (i < lines.length) {
      const line = lines[i];

      // Nuevo chain de nivel superior → salir del loop interno
      if (line.match(/^  \S+:\s*$/) && !line.match(/^\s{4}/)) break;

      // description
      const descMatch = line.match(/^    description:\s*"?([^"]*)"?\s*$/);
      if (descMatch) { chain.description = descMatch[1].trim(); i++; continue; }

      // step: - agent:
      const agentMatch = line.match(/^\s+-\s+agent:\s+(\S+)/);
      if (agentMatch) {
        const step: ChainStep = { agent: agentMatch[1], prompt: "" };
        chain.steps.push(step);
        i++;

        // prompt (puede ser literal block |)
        if (i < lines.length && lines[i].match(/^\s+prompt:\s*\|?\s*$/)) {
          i++;
          const promptLines: string[] = [];
          // Detecta la indentación del primer línea del bloque
          const indentMatch = lines[i]?.match(/^(\s+)/);
          const baseIndent = indentMatch ? indentMatch[1].length : 10;

          while (i < lines.length) {
            const pl = lines[i];
            // Si la línea tiene menos indentación (o es otro step/campo), corta
            if (pl.trim() === "" || (pl.match(/^\s+/) && pl.match(/^\s+/)[0].length >= baseIndent)) {
              promptLines.push(pl.slice(baseIndent));
              i++;
            } else if (pl.match(/^\s+-\s+agent:/) || pl.match(/^\s{4}\w/)) {
              break;
            } else {
              promptLines.push(pl.slice(baseIndent));
              i++;
            }
          }
          step.prompt = promptLines.join("\n").trim();
        } else if (i < lines.length) {
          const inlineMatch = lines[i].match(/^\s+prompt:\s+(.+)$/);
          if (inlineMatch) {
            step.prompt = inlineMatch[1].replace(/^["']|["']$/g, "");
            i++;
          }
        }
        continue;
      }

      i++;
    }
  }

  return chains;
}

// ── Widget helpers ─────────────────────────────────────────────────────────

const STATUS_ICON: Record<string, string> = {
  pending: "○",
  running: "◉",
  done: "✓",
  error: "✗",
};

const STATUS_COLOR: Record<string, string> = {
  pending: "dim",
  running: "accent",
  done: "success",
  error: "error",
};

function renderStepCard(
  state: StepState,
  colW: number,
  theme: any
): string[] {
  const inner = colW - 2;
  const clip = (s: string, max: number) =>
    s.length > max ? s.slice(0, max - 3) + "…" : s;

  const name = state.agent.replace(/^cortex-/, "").replace(/-/g, " ");
  const nameStr = theme.fg("accent", theme.bold(clip(name, inner)));
  const nameLen = Math.min(name.length, inner);

  const icon = STATUS_ICON[state.status] ?? "?";
  const elapsed = state.elapsed > 0 ? ` ${Math.round(state.elapsed / 1000)}s` : "";
  const statusRaw = `${icon} ${state.status}${elapsed}`;
  const statusStr = theme.fg(STATUS_COLOR[state.status] ?? "dim", statusRaw);
  const statusLen = statusRaw.length;

  const workRaw = state.lastLine
    ? clip(state.lastLine, Math.min(50, inner - 1))
    : "—";
  const workStr = state.lastLine
    ? theme.fg("muted", workRaw)
    : theme.fg("dim", workRaw);
  const workLen = workRaw.length;

  const top = "┌" + "─".repeat(inner) + "┐";
  const bot = "└" + "─".repeat(inner) + "┘";
  const row = (content: string, visLen: number) =>
    theme.fg("dim", "│") +
    content +
    " ".repeat(Math.max(0, inner - visLen)) +
    theme.fg("dim", "│");

  return [
    theme.fg("dim", top),
    row(" " + nameStr, 1 + nameLen),
    row(" " + statusStr, 1 + statusLen),
    row(" " + workStr, 1 + workLen),
    theme.fg("dim", bot),
  ];
}

// ── Subprocess runner ──────────────────────────────────────────────────────

function runAgentStep(
  agent: AgentDef,
  task: string,
  sessionFile: string,
  model: string,
  onProgress: (line: string) => void
): Promise<{ output: string; ok: boolean; elapsed: number }> {
  const args = [
    "--mode", "json",
    "-p",
    "--no-extensions",
    "--model", model,
    "--tools", agent.tools,
    "--thinking", "off",
    "--append-system-prompt", agent.systemPrompt,
    "--session", sessionFile,
    task,
  ];

  const start = Date.now();
  const chunks: string[] = [];

  return new Promise((resolve) => {
    const proc = spawn("pi", args, {
      stdio: ["ignore", "pipe", "pipe"],
      env: { ...process.env },
    });

    let buf = "";
    proc.stdout!.setEncoding("utf-8");
    proc.stdout!.on("data", (chunk: string) => {
      buf += chunk;
      const lines = buf.split("\n");
      buf = lines.pop() || "";
      for (const line of lines) {
        if (!line.trim()) continue;
        try {
          const ev = JSON.parse(line);
          if (ev.type === "message_update") {
            const delta = ev.assistantMessageEvent;
            if (delta?.type === "text_delta" && delta.delta) {
              chunks.push(delta.delta);
              const full = chunks.join("");
              const last = full.split("\n").filter((l: string) => l.trim()).pop() || "";
              onProgress(last);
            }
          }
        } catch {}
      }
    });

    proc.stderr!.setEncoding("utf-8");
    proc.stderr!.on("data", () => {});

    proc.on("close", (code) => {
      resolve({
        output: chunks.join(""),
        ok: code === 0,
        elapsed: Date.now() - start,
      });
    });
  });
}

// ── Extension ──────────────────────────────────────────────────────────────

export default function (pi: ExtensionAPI) {
  pi.registerMessageRenderer("cortex-agent-chain", (message, _options, theme) => {
    const content = typeof message.content === "string" ? message.content : "";
    return new Text(theme.fg("accent", "⬡ chain: ") + content, 0, 0);
  });

  let chains: ChainDef[] = [];
  let agents: Map<string, AgentDef> = new Map();
  let activeChain: ChainDef | null = null;
  let stepStates: StepState[] = [];
  let sessionDir = "";

  function activateChain(chain: ChainDef, ctx: any) {
    activeChain = chain;
    stepStates = chain.steps.map(s => ({
      agent: s.agent,
      status: "pending" as const,
      elapsed: 0,
      lastLine: "",
    }));
    updateWidget(ctx);
  }

  function loadConfig(cwd: string) {
    agents = scanAgents(cwd);
    sessionDir = join(cwd, ".pi", "agent-sessions");
    if (!existsSync(sessionDir)) {
      try { mkdirSync(sessionDir, { recursive: true }); } catch {}
    }

    const chainPath = join(cwd, ".pi", "agents", "agent-chain.yaml");
    if (existsSync(chainPath)) {
      try {
        chains = parseChainYaml(readFileSync(chainPath, "utf-8"));
      } catch (e) {
        chains = [];
      }
    }
  }

  function updateWidget(ctx: any) {
    ctx.ui.setWidget("cortex-chain", (_tui: any, theme: any) => {
      return {
        render(width: number): string[] {
          if (!activeChain || stepStates.length === 0) {
            return [theme.fg("dim", " Sin pipeline activo. Usa /chain para seleccionar.")];
          }

          const arrowW = 5; // " ──▶ "
          const cols = stepStates.length;
          const colW = Math.max(14, Math.floor((width - arrowW * (cols - 1)) / cols));
          const cards = stepStates.map(s => renderStepCard(s, colW, theme));
          const cardH = cards[0].length;
          const arrowRow = 2;
          const out: string[] = [];

          for (let row = 0; row < cardH; row++) {
            let line = cards[0][row];
            for (let c = 1; c < cols; c++) {
              line += row === arrowRow
                ? theme.fg("dim", " ──▶ ")
                : " ".repeat(arrowW);
              line += cards[c][row];
            }
            out.push(line);
          }
          return out;
        },
        invalidate() {},
      };
    });
  }

  async function executeChain(chain: ChainDef, initialInput: string, ctx: any) {
    activeChain = chain;
    stepStates = chain.steps.map(s => ({
      agent: s.agent,
      status: "pending" as const,
      elapsed: 0,
      lastLine: "",
    }));
    updateWidget(ctx);

    const modelObj = ctx.model;
    const model = modelObj
      ? `${modelObj.provider}/${modelObj.id}`
      : "anthropic/claude-sonnet-4-20250514";

    let prevOutput = initialInput;

    for (let i = 0; i < chain.steps.length; i++) {
      const step = chain.steps[i];
      const state = stepStates[i];
      const agentDef = agents.get(step.agent.toLowerCase());

      if (!agentDef) {
        state.status = "error";
        state.lastLine = `Agente "${step.agent}" no encontrado en .pi/agents/`;
        updateWidget(ctx);
        ctx.ui.notify(`⚠ ${state.lastLine}`, "warning");
        break;
      }

      state.status = "running";
      updateWidget(ctx);

      // Sustituye las variables de template
      const task = step.prompt
        .replace(/\$INPUT/g, prevOutput)
        .replace(/\$ORIGINAL/g, initialInput);

      const sessionFile = join(sessionDir, `chain-${step.agent}.json`);

      const tickTimer = setInterval(() => {
        state.elapsed += 1000;
        updateWidget(ctx);
      }, 1000);

      const result = await runAgentStep(
        agentDef,
        task,
        sessionFile,
        model,
        (line) => {
          state.lastLine = line;
          updateWidget(ctx);
        }
      );

      clearInterval(tickTimer);
      state.status = result.ok ? "done" : "error";
      state.elapsed = result.elapsed;
      updateWidget(ctx);

      if (!result.ok) {
        ctx.ui.notify(`⚠ Paso ${i + 1} (${step.agent}) terminó con error`, "warning");
        break;
      }

      prevOutput = result.output || prevOutput;
    }

    const allDone = stepStates.every(s => s.status === "done");
    ctx.ui.notify(
      allDone
        ? `✓ Pipeline "${chain.key}" completado`
        : `⚠ Pipeline "${chain.key}" terminado con errores`,
      allDone ? "success" : "warning"
    );
  }

  // ── /chain — selector de pipeline ──
  pi.registerCommand("chain", {
    description: "Selecciona y ejecuta un pipeline Cortex",
    async handler(args: string, ctx: any) {
      const cwd = process.cwd();
      loadConfig(cwd);

      if (chains.length === 0) {
        ctx.ui.notify("⚠ No se encontraron pipelines en .pi/agents/agent-chain.yaml", "warning");
        return;
      }

      // ctx.ui.select recibe título y array de STRINGS simples
      const options: string[] = chains.map(c => {
        const steps = c.steps.map(s => s.agent.replace("cortex-", "")).join("→");
        return `${c.key}  [${steps}]  ${c.description ? "— " + c.description : ""}`;
      });

      const selected: string | undefined = await ctx.ui.select(
        "⬡ Cortex — Seleccionar Pipeline",
        options
      );

      if (selected === undefined) {
        ctx.ui.notify("Selección cancelada", "info");
        return;
      }

      const chainKey = selected.split("  ")[0].trim();
      const chain = chains.find(c => c.key === chainKey);
      if (!chain) {
        ctx.ui.notify("⚠ Pipeline no encontrado", "warning");
        return;
      }

      // Si el usuario pasó args, úsalos como input; si no, pide confirmación de tarea
      const input = args.trim();
      if (!input) {
        ctx.ui.notify(`Pipeline "${chain.key}" seleccionado. Escribí tu tarea en el chat y Pi la ejecutará en el pipeline.`, "info");
        pi.sendMessage({
          customType: "cortex-agent-chain",
          content: `Pipeline activo: ${chain.key}\n${chain.description}\nPasos: ${chain.steps.map(s => s.agent).join(" → ")}\n\nEscribí tu tarea y se ejecutará el pipeline.`,
          display: true,
        });
        // Registra el chain como activo para que el próximo mensaje lo dispare
        activeChain = chain;
        activateChain(chain, ctx);
        return;
      }

      await executeChain(chain, input, ctx);
    },
  });

  // ── /chain-list — listar pipelines ──
  pi.registerCommand("chain-list", {
    description: "Lista todos los pipelines Cortex disponibles",
    handler(_args: string, ctx: any) {
      const cwd = process.cwd();
      loadConfig(cwd);

      if (chains.length === 0) {
        ctx.ui.notify("No hay pipelines definidos en agent-chain.yaml", "warning");
        return;
      }

      const content = chains.map(c => {
        const stepNames = c.steps.map(s => s.agent.replace("cortex-", "")).join(" → ");
        return `${c.key} — ${c.description}\n  [${stepNames}]`;
      }).join("\n\n");

      pi.sendMessage({
        customType: "cortex-agent-chain",
        content: `Pipelines Cortex disponibles:\n\n${content}`,
        display: true,
      });
    },
  });

  // ── Carga config al arrancar ──
  pi.on("session_start", (_event: any, ctx: any) => {
    const cwd = process.cwd();
    loadConfig(cwd);
    if (chains.length > 0) {
      ctx.ui.notify(
        `⬡ Cortex Chain: ${chains.length} pipeline${chains.length !== 1 ? "s" : ""} → /chain para ejecutar`,
        "info"
      );
    }
  });
}

/**
 * cortex-autopilot.ts — Hotkeys virtuales + gates + sugerencias contextuales
 *
 * F2 del overhaul UX (ver docs/multi-ide-mcp-hardening/PI-COCKPIT-UX/).
 *
 * Tres responsabilidades:
 *
 *   1. HOTKEYS VIRTUALES (interceptor del evento ``input``).
 *      Atajos cortos prefijados con ``:`` que el usuario tipea en el
 *      prompt. El handler los captura ANTES de que lleguen al agent y
 *      los traduce a slash commands o notificaciones. Cero costo de
 *      tokens. Prefijo ``:`` para no chocar con texto natural.
 *
 *      Mapeo actual:
 *
 *        :n  → ejecutar/anunciar la sugerencia activa del cockpit
 *        :t  → abrir panel team (F5; placeholder hasta F5)
 *        :d  → hint para cambiar a documenter
 *        :r  → /cortex-role
 *        :m  → /cortex-mode
 *        :l  → /cortex-net (status de red)
 *        :?  → mostrar lista de hotkeys disponibles
 *
 *   2. GATES DE GOBERNANZA (interceptor ``tool_call``).
 *      Detección temprana de violaciones de contrato Cortex sin romper
 *      el flujo (el backend ya tiene sus propios gates más estrictos —
 *      esto es feedback temprano en la UI, no enforcement).
 *
 *      Por ahora: warning si ``cortex_create_spec`` se invoca sin
 *      ``cortex_sync_ticket`` previo en este proceso.
 *
 *   3. SUGERENCIAS CONTEXTUALES (computa ``cortexState.suggestion``).
 *      Tras cada cambio de estado relevante (before_agent_start,
 *      turn_end), recalcula la próxima acción sugerida y la escribe al
 *      singleton. El cockpit la renderiza con su hotkey si la tiene.
 *
 * No registra ningún slash command propio en F2 — los hotkeys
 * virtuales delegan a comandos existentes (cortex-net.ts).
 */

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
// Bugfix mayo 2026: import desde .pi/lib/ (ver cortex-cockpit.ts y
// docs/multi-ide-mcp-hardening/PI-COCKPIT-UX/README.md § 8).
import {
  cortexState,
  subscribe as subscribeCortexState,
  update as updateCortexState,
  type Suggestion,
} from "../lib/cortex-state";

// Bugfix mayo 2026: Pi v0.77 trata el prefijo ``:`` como un comando
// bash (igual que ``!``), así que las hotkeys :n :t :d etc. terminan
// disparando un shell command en vez de pasar por el handler de
// ``input``. Solución: registrar slash commands cortos con prefijo
// ``cx-`` (de "cortex") como aliases de las acciones más usadas. Pi
// los manda al handler registrado garantizado.
//
// Nota: los alias cx- DUPLICADOS (/cx-team, /cx-role, /cx-mode, /cx-model,
// /cx-master) se eliminaron — usá los nombres completos (/cortex-team, etc.).
// Acá sólo viven /cx-next y /cx-help, que NO tienen comando de nombre completo:
//
//   /cx-next  → anuncia la sugerencia activa
//   /cx-help  → lista los atajos

// ── Sugerencias contextuales ───────────────────────────────────────────────

/**
 * Calcula la próxima acción recomendada según el estado actual.
 *
 * Reglas en orden de prioridad (la primera que matchea gana):
 *
 *   1. Sin sesión → tipear tarea para activar sync.
 *   2. Sync activo, sin checkpoints → esperar que sync persista spec.
 *   3. Sin agent activo aún → esperar primer cambio de agent.
 *   4. Documenter activo → cerrar con cortex_close_session.
 *   5. Middle activo, sin peers conectados → abrir terminales role-*.
 *   6. Middle activo, peers conectados → seguir coordinando.
 *
 * Devuelve null cuando no hay nada interesante que sugerir.
 */
function computeSuggestion(): Suggestion | null {
  // 1. Standby
  if (!cortexState.sessionId) {
    return {
      label: "Tipeá tu tarea — cortex-sync va a abrir la sesión automáticamente",
      hotkey: null,
      reason: "no hay Cortex Session activa",
    };
  }

  // 2. Sync activo
  if (cortexState.activeAgentName === "cortex-sync") {
    return {
      label: "Esperando que cortex-sync persista la spec",
      hotkey: null,
      reason: "sync corriendo (B' anchor, afuera de la red)",
    };
  }

  // 3. Sin agent del medio asignado
  if (!cortexState.myRole) {
    return {
      label: "Cambiá a un agent del medio (/system → cortex-SDDwork u otro)",
      hotkey: null,
      reason: "no estás registrado en la red todavía",
    };
  }

  // 4. Documenter activo → cerrar
  if (cortexState.myRole === "documenter") {
    return {
      label: "Llamá cortex_documenter_briefing + cortex_close_session para cerrar",
      hotkey: null,
      reason: "documenter activo, listo para cerrar",
    };
  }

  // 5. Middle activo sin peers conectados
  if (cortexState.peers.length === 0) {
    return {
      label: "Sin peers en la red — abrí el team con /cortex-team",
      hotkey: null,
      reason: "deep track requiere multi-terminal",
    };
  }

  // 6. Middle activo con peers
  return {
    label: "Coordiná con peers desde /cortex (mandar mensaje / broadcast)",
    hotkey: null,
    reason: `${cortexState.peers.length} peers conectados`,
  };
}

/** Igualdad por valor de sugerencias (para no re-escribir ni loopear). */
function suggestionsEqual(a: Suggestion | null, b: Suggestion | null): boolean {
  if (a === b) return true;
  if (!a || !b) return false;
  return a.label === b.label && a.hotkey === b.hotkey && a.reason === b.reason;
}

// ── Extension ──────────────────────────────────────────────────────────────

export default function (pi: ExtensionAPI) {
  // Set local de tools llamadas en este proceso. Sirve para detectar
  // ``cortex_create_spec`` sin ``cortex_sync_ticket`` previo. NO es
  // perfecto en multi-terminal (otra Pi puede haber llamado sync_ticket),
  // pero el flujo canónico es que sync corre en UN solo proceso antes
  // de que los workers entren a la red — así que el set local cubre el
  // caso real. El backend MCP tiene su propio gate más robusto.
  const toolsCalled = new Set<string>();
  let unsub: (() => void) | null = null;

  // ── Slash commands cortos (reemplazo de las hotkeys ":" que Pi v0.77
  //    interpretaba como bash). Ver bloque de comentario arriba.
  pi.registerCommand("cx-next", {
    description: "Anuncia la próxima acción sugerida según el estado actual",
    async handler(_args, ctx) {
      if (cortexState.suggestion) {
        ctx.ui.notify(
          `→ ${cortexState.suggestion.label} (${cortexState.suggestion.reason})`,
          "info"
        );
      } else {
        ctx.ui.notify(
          "Sin sugerencia activa. Tipeá tu tarea o abrí /cortex.",
          "info"
        );
      }
    },
  });

  pi.registerCommand("cx-help", {
    description: "Lista los atajos slash de Cortex Pi 2.5+net",
    async handler(_args, ctx) {
      ctx.ui.notify(
        "Atajos Cortex Pi 2.5+net:\n" +
          "  /cortex      panel grande (todas las acciones)\n" +
          "  /cx-next     próxima acción sugerida\n" +
          "  /cortex-team auto-spawn de terminales\n" +
          "  /cortex-role cambiar rol\n" +
          "  /cortex-mode cambiar modo (Full/Solo)\n" +
          "  /cx-help     esta ayuda\n" +
          "  /cortex-net  status detallado de la red\n" +
          "  /system      cambiar agent activo",
        "info"
      );
    },
  });

  // Acá quedan sólo /cx-next y /cx-help (propios de autopilot, sin gemelo de
  // nombre completo). Los alias cx- duplicados se eliminaron del bundle.

  // ── tool_call: gates de gobernanza ───────────────────────────────────
  pi.on("tool_call", async (event, ctx) => {
    // Bugfix may 2026: el ToolCallEvent de Pi entrega event.toolName
    // (ver types.d.ts CustomToolCallEvent y damage-control.ts en este mismo
    // bundle). La versión previa leía event.tool?.name / event.name →
    // siempre undefined → el gate jamás disparaba (código muerto).
    const toolName: string = (event as any).toolName ?? "";
    if (!toolName) return;

    toolsCalled.add(toolName);

    // Gate: cortex_create_spec sin cortex_sync_ticket
    if (
      toolName === "cortex_create_spec" &&
      !toolsCalled.has("cortex_sync_ticket")
    ) {
      ctx?.ui?.notify(
        "⚠ Llamando cortex_create_spec sin cortex_sync_ticket previo. " +
          "El backend MCP va a rechazarlo con violación de gobernanza. " +
          "Ejecutá cortex_sync_ticket primero.",
        "warning"
      );
      // No bloqueamos — el backend ya rechaza. Esto es solo feedback temprano.
    }
  });

  // ── before_agent_start: recalcular sugerencia ───────────────────────
  pi.on("before_agent_start", async () => {
    updateCortexState({ suggestion: computeSuggestion() });
  });

  // ── turn_end: recalcular sugerencia (refresca contexto) ─────────────
  pi.on("turn_end", async () => {
    updateCortexState({ suggestion: computeSuggestion() });
  });

  // ── session_start: sembrar primera sugerencia + suscribir refresh ─────
  pi.on("session_start", async (_event, ctx) => {
    updateCortexState({ suggestion: computeSuggestion() });

    // 1a: la sugerencia se recalcula cuando CUALQUIER parte del estado
    // cambia (sessionId/myRole/peers vía la red), no solo en eventos de Pi.
    // Antes quedaba stale (un worker que no hace turns mostraba "tipeá tu
    // tarea" para siempre). Deferimos con queueMicrotask y sólo escribimos
    // si cambió, para no loopear con el propio update() (que re-notifica).
    if (!unsub) {
      unsub = subscribeCortexState(() => {
        queueMicrotask(() => {
          const next = computeSuggestion();
          if (!suggestionsEqual(next, cortexState.suggestion)) {
            updateCortexState({ suggestion: next });
          }
        });
      });
    }

    ctx.ui.notify(
      "⬡ cortex-autopilot: tipeá /cx-help para ver atajos. " +
        "Sugerencias contextuales activas.",
      "info"
    );
  });

  // ── session_shutdown: limpiar estado local ──────────────────────────
  pi.on("session_shutdown", async () => {
    toolsCalled.clear();
    if (unsub) {
      unsub();
      unsub = null;
    }
    // No notify acá: Pi se está cerrando, no llega.
    // No reset del singleton: cortex-cockpit ya lo hace en su shutdown.
  });
}

files.project:.pi/extensions/cortex-cockpit.ts:
/**
 * cortex-cockpit.ts — Widget persistente + status bar de Cortex Pi 2.5+net
 *
 * F1 del overhaul UX (ver docs/multi-ide-mcp-hardening/PI-COCKPIT-UX/).
 *
 * Lo que hace:
 *
 *   1. Widget arriba del editor (``ctx.ui.setWidget("cortex-cockpit", ...)``)
 *      que muestra estado de la sesión, rol propio, peers en la red y
 *      tráfico reciente. Read-only — la interacción pasa por /cortex (F4)
 *      o por las hotkeys virtuales de cortex-autopilot (F2).
 *
 *   2. Status bar multi-key (``ctx.ui.setStatus(...)``) con tres slots
 *      siempre visibles aunque el widget quede fuera de viewport:
 *        - cortex-session : ⬡ <id> · <tiempo>
 *        - cortex-role    : <rol> · MASTER/WORKER
 *        - cortex-peers   : <count> peers (<idle>/<busy>)
 *
 *   3. Suscriptor del singleton ``_cortex-state``: cuando cortex-net o
 *      cortex-autopilot mutan el estado, el cockpit se redibuja sin
 *      polling extra. Igualmente hay un ``setInterval`` de respaldo
 *      para leer ``.cortex/session.lock`` por si la sesión cambia
 *      fuera-de-banda (otra Pi la cerró, p.ej.).
 *
 * NO hace:
 *
 *   - No captura keyboard (los widgets persistentes no reciben input
 *     según la doc de Pi). Las hotkeys son responsabilidad de F2.
 *   - No llama tools MCP. El estado lo lee del singleton + del
 *     session.lock + del audit/transcript log que ya escribe cortex-net.
 *   - No abre paneles modales. Eso es F4 (``cortex-panel.ts``).
 *
 * Uso: cargada automáticamente por settings.json
 *      (defaultExtensions: [..., ".pi/extensions/cortex-cockpit.ts"]).
 */

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
// truncateToWidth respeta los ANSI escape codes al cortar (a diferencia
// de String.slice). visibleWidth nos dice cuántas "columnas" ocupa un
// string con escapes embebidos. Indispensable para no crashear Pi con
// "Rendered line N exceeds terminal width".
import { truncateToWidth, visibleWidth } from "@mariozechner/pi-tui";
import { existsSync, readFileSync, statSync } from "fs";
import { join } from "path";
// Bugfix mayo 2026: el singleton vive en .pi/lib/ para evitar la
// doble instancia que provoca el autoloader de Pi v0.77 (ver
// docs/multi-ide-mcp-hardening/PI-COCKPIT-UX/README.md § 8).
import {
  cortexState,
  subscribe,
  update,
  reset,
} from "../lib/cortex-state";

// ── Constantes ─────────────────────────────────────────────────────────────

const WIDGET_ID = "cortex-cockpit";
const STATUS_SESSION = "cortex-session";
const STATUS_ROLE = "cortex-role";
const STATUS_PEERS = "cortex-peers";

/** Período del polling de respaldo en ms (lee session.lock por si cambió). */
const REFRESH_INTERVAL_MS = 3000;

// ── Helpers de derivación de estado ────────────────────────────────────────

/**
 * Lee ``<cwd>/.cortex/session.lock`` y devuelve el session_id, o null.
 *
 * Best-effort: cualquier error de IO devuelve null. Usado por el polling
 * de respaldo para detectar si la sesión cambió sin que el hook de
 * cortex-net lo haya propagado (p.ej. otro Pi cerró la sesión).
 */
function readSessionLock(cwd: string): { id: string; mtime: number } | null {
  const lock = join(cwd, ".cortex", "session.lock");
  if (!existsSync(lock)) return null;
  try {
    const raw = readFileSync(lock, "utf-8").trim();
    if (!raw) return null;
    const st = statSync(lock);
    return { id: raw, mtime: st.mtimeMs };
  } catch {
    return null;
  }
}

/** Formato compacto "12m" / "1h32m" / "47s" para mostrar duración. */
function formatDuration(ms: number): string {
  const s = Math.floor(ms / 1000);
  if (s < 60) return `${s}s`;
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m`;
  const h = Math.floor(m / 60);
  return `${h}h${m - h * 60}m`;
}

/** Acorta el session_id para mostrar (mantiene la fecha y el primer slug). */
function shortSessionId(id: string): string {
  // Formato canónico: YYYY-MM-DD_<slug>. Lo mostramos completo pero
  // truncado a ~28 chars para que entre en una línea típica.
  if (id.length <= 32) return id;
  return id.slice(0, 29) + "…";
}

// ── Render ──────────────────────────────────────────────────────────────────

/**
 * Renderiza el widget grande. Devuelve líneas listas para Pi.
 *
 * Estados que cubre F1:
 *
 *   - Standby: sin sessionId. Mensaje breve.
 *   - Sync activo: hay sessionId y el agent activo es cortex-sync (B').
 *   - Middle: hay sessionId y el rol propio es uno de los 7.
 *   - Documenter: hay sessionId y el rol propio es "documenter".
 *
 * Render más sofisticado (sugerencias contextuales, tráfico reciente,
 * conteo de checkpoints) llegan con F2/F3.
 */
function renderCockpit(theme: any, width: number): string[] {
  const lines: string[] = [];
  // El widget se renderiza al ancho de la terminal. Si Pi pasa 0 o algo
  // raro, tope mínimo de 40 cols. Tope superior 120 para que no se vea
  // ridículo en monitores anchos.
  const W = Math.max(40, Math.min(width || 80, 120));

  // ── Standby ───────────────────────────────────────────────────────────
  if (!cortexState.sessionId) {
    lines.push(theme.fg("muted", "⬡ Cortex · standby"));
    lines.push(theme.fg("dim", "  Sin sesión activa — tipeá tu tarea para empezar"));
    return finalize(lines, W);
  }

  // ── Con sesión ────────────────────────────────────────────────────────
  const elapsed = cortexState.sessionOpenedAt
    ? formatDuration(Date.now() - cortexState.sessionOpenedAt)
    : "—";
  const role = cortexState.activeAgentName === "cortex-sync"
    ? "sync (B' — afuera de la red)"
    : cortexState.myRole ?? "(no en la red)";
  // Modo: MASTER si vos levantaste el hub; WORKER si te conectaste a un
  // hub externo; "—" si ni siquiera estás en la red todavía (caso típico
  // tras un session_start sin lock — cortex-net espera al lock para
  // levantar el hub).
  const mode = !cortexState.myRole
    ? cortexState.activeAgentName === "cortex-sync"
      ? theme.fg("dim", "sync")
      : theme.fg("dim", "STANDBY")
    : cortexState.isMaster
    ? theme.fg("accent", "MASTER")
    : theme.fg("muted", "WORKER");

  // Línea 1: header con session id + tiempo + master/worker
  lines.push(
    theme.fg("accent", "⬡ CORTEX") +
      " · " +
      theme.fg("text", shortSessionId(cortexState.sessionId)) +
      theme.fg("dim", ` · ${elapsed}`) +
      theme.fg("dim", " — ") +
      mode
  );

  // Línea 2: rol propio + agent activo
  const agentLabel = cortexState.activeAgentName ?? "(ninguno)";
  lines.push(
    theme.fg("dim", "  Rol: ") +
      theme.fg("text", String(role)) +
      theme.fg("dim", " · agent: ") +
      theme.fg("text", agentLabel)
  );

  // Línea 3+: peers
  if (cortexState.peers.length === 0) {
    const hint =
      cortexState.activeAgentName === "cortex-sync"
        ? "(en sync; peers entran al cambiar de rol)"
        : "(ninguno — /cortex-team o just role-*)";
    lines.push(theme.fg("dim", "  Peers: ") + theme.fg("muted", hint));
  } else {
    const peerLabels = cortexState.peers.map((p) => {
      const self = p.role === cortexState.myRole ? "→" : " ";
      const status = p.status ?? "?";
      const statusColor =
        status === "idle"
          ? "success"
          : status === "busy"
          ? "warning"
          : status === "observe"
          ? "accent"
          : "muted";
      return (
        theme.fg("dim", `${self} `) +
        theme.fg("text", p.role.padEnd(14)) +
        theme.fg(statusColor, status)
      );
    });
    lines.push(theme.fg("dim", `  Peers (${cortexState.peers.length}):`));
    // 2 peers por línea para no desbordar en terminales angostas.
    for (let i = 0; i < peerLabels.length; i += 2) {
      const pair = peerLabels.slice(i, i + 2).join("  ·  ");
      lines.push("    " + pair);
    }
  }

  // Cola de mensajes entrantes (rediseño may-2026). Visible para que nunca
  // queden mensajes esperando sin que el usuario lo sepa.
  if (cortexState.inbound.length > 0) {
    const froms = [...new Set(cortexState.inbound.map((m) => m.from))].join(", ");
    lines.push(
      theme.fg("warning", `  📨 ${cortexState.inbound.length} en cola`) +
        theme.fg("dim", ` (de ${froms}) · `) +
        theme.fg("accent", "/cx-inbox")
    );
  }

  // Sugerencia (la popula F2)
  if (cortexState.suggestion) {
    const hk = cortexState.suggestion.hotkey
      ? theme.fg("accent", ` [${cortexState.suggestion.hotkey}]`)
      : "";
    lines.push(
      theme.fg("dim", "  → ") +
        theme.fg("text", cortexState.suggestion.label) +
        hk
    );
  }

  // Footer: hints de comandos. Corto a propósito para no exceder
  // terminales angostas.
  lines.push(
    theme.fg("dim", "  ") +
      theme.fg("accent", "/cortex") +
      theme.fg("dim", " panel · ") +
      theme.fg("accent", "/cx-help") +
      theme.fg("dim", " atajos")
  );

  return finalize(lines, W);
}

/**
 * Aplica truncateToWidth a cada línea para garantizar que ninguna excede
 * el ancho de la terminal. Pi crashea con uncaughtException si una línea
 * supera el width. truncateToWidth preserva los escape codes ANSI al
 * cortar — no podemos usar slice porque cortaría en medio de un escape.
 */
function finalize(lines: string[], width: number): string[] {
  return lines.map((l) => (visibleWidth(l) > width ? truncateToWidth(l, width) : l));
}

/** Actualiza la status bar multi-key (3 slots). Independiente del widget. */
function updateStatusBar(ctx: any): void {
  if (!cortexState.sessionId) {
    ctx.ui.setStatus(STATUS_SESSION, "⬡ standby");
    ctx.ui.setStatus(STATUS_ROLE, "");
    ctx.ui.setStatus(STATUS_PEERS, "");
    return;
  }

  // Slot 1: sesión + tiempo
  const elapsed = cortexState.sessionOpenedAt
    ? formatDuration(Date.now() - cortexState.sessionOpenedAt)
    : "—";
  ctx.ui.setStatus(
    STATUS_SESSION,
    `⬡ ${shortSessionId(cortexState.sessionId)} · ${elapsed}`
  );

  // Slot 2: rol + master/worker. Espeja la lógica de 3 estados del widget
  // (STANDBY / sync / role·MASTER|WORKER). Antes mostraba "— · WORKER"
  // cuando myRole era null, contradiciendo al widget de arriba.
  let roleStatus: string;
  if (!cortexState.myRole) {
    roleStatus = cortexState.activeAgentName === "cortex-sync" ? "sync" : "STANDBY";
  } else {
    roleStatus = `${cortexState.myRole} · ${cortexState.isMaster ? "MASTER" : "WORKER"}`;
  }
  ctx.ui.setStatus(STATUS_ROLE, roleStatus);

  // Slot 3: peers (+ 📨N si hay mensajes en cola)
  const mail = cortexState.inbound.length > 0 ? ` 📨${cortexState.inbound.length}` : "";
  if (cortexState.peers.length === 0) {
    ctx.ui.setStatus(STATUS_PEERS, "0 peers" + mail);
  } else {
    const idle = cortexState.peers.filter((p) => p.status === "idle").length;
    const busy = cortexState.peers.filter((p) => p.status === "busy").length;
    ctx.ui.setStatus(
      STATUS_PEERS,
      `${cortexState.peers.length} peers (${idle}i/${busy}b)` + mail
    );
  }
}

// ── Extensión ──────────────────────────────────────────────────────────────

export default function (pi: ExtensionAPI) {
  let pollHandle: NodeJS.Timeout | null = null;
  let unsubscribe: (() => void) | null = null;
  let lastLockMtime = 0;

  /**
   * Vuelve a registrar el widget y actualiza la status bar.
   *
   * setWidget acepta una factory que devuelve un Component-like; cada
   * llamada reemplaza al anterior con el mismo id. Pi se encarga del
   * redraw real.
   */
  function refresh(ctx: any): void {
    ctx.ui.setWidget(
      WIDGET_ID,
      (_tui: any, theme: any) => ({
        render(width: number): string[] {
          return renderCockpit(theme, width);
        },
        invalidate() {
          /* no-op: el render es puro sobre cortexState */
        },
      }),
      { placement: "aboveEditor" }
    );
    updateStatusBar(ctx);
  }

  /**
   * Polling de respaldo: lee session.lock cada N segundos y actualiza
   * sessionId si cambió (otra Pi cerró/abrió una sesión).
   *
   * Si cortex-net está cargado, este polling es redundante en el
   * camino feliz — el hook session_start de cortex-net ya popula
   * sessionId. El polling lo agrego de igual modo para que el cockpit
   * funcione standalone (sin cortex-net cargado).
   */
  function pollLock(ctx: any): void {
    if (!cortexState.cwd) return;
    const lock = readSessionLock(cortexState.cwd);
    if (!lock) {
      if (cortexState.sessionId !== null) {
        // sesión que existía ya no existe — limpiar
        update({
          sessionId: null,
          sessionOpenedAt: null,
        });
        refresh(ctx);
      }
      return;
    }
    if (lock.id !== cortexState.sessionId || lock.mtime !== lastLockMtime) {
      lastLockMtime = lock.mtime;
      update({
        sessionId: lock.id,
        sessionOpenedAt: cortexState.sessionOpenedAt ?? lock.mtime,
      });
      refresh(ctx);
    }
  }

  // ── session_start ─────────────────────────────────────────────────────
  pi.on("session_start", async (_event, ctx) => {
    // Estado inicial. cortex-net (si está cargado) va a sobrescribir
    // isMaster / peers / myRole en sus propios hooks; nosotros sembramos
    // lo que se puede deducir solo del filesystem.
    const lock = readSessionLock(ctx.cwd);
    lastLockMtime = lock?.mtime ?? 0;
    update({
      cwd: ctx.cwd,
      sessionId: lock?.id ?? null,
      sessionOpenedAt: lock?.mtime ?? null,
      myModel: ctx.model
        ? `${ctx.model.provider ?? "?"}/${ctx.model.id ?? "?"}`
        : null,
    });

    // Subscripción al singleton: cualquier ``update(...)`` desde otra
    // extensión nos hace re-renderizar.
    unsubscribe = subscribe(() => refresh(ctx));

    refresh(ctx);
    pollHandle = setInterval(() => pollLock(ctx), REFRESH_INTERVAL_MS);
  });

  // ── before_agent_start: NO se usa, a propósito ───────────────────────
  // Bugfix may 2026 (causa raíz del STANDBY): Pi v0.77 NO expone el agent
  // activo en ningún evento ni en ctx. Verificado contra los tipos
  // instalados: BeforeAgentStartEvent = { type, prompt, images?,
  // systemPrompt, systemPromptOptions } — sin agentName. La versión previa
  // leía (event as any).agentName → SIEMPRE undefined → escribía
  // activeAgentName:null / myRole:null EN CADA TURNO, pisando lo que
  // /system (system-select) había fijado y devolviendo el cockpit a
  // STANDBY. El cockpit es lector PURO: la identidad de rol la administra
  // system-select y nos enteramos vía subscribe() → refresh().

  // ── turn_end ─────────────────────────────────────────────────────────
  pi.on("turn_end", async (_event, ctx) => {
    // Defensa: re-poblar cwd si por alguna razón se perdió (observado
    // en runtime: /cortex-team falla con "no hay cwd cacheado" aunque
    // session_start del cockpit corrió. Mejor poblarlo de defensiva).
    if (!cortexState.cwd && ctx?.cwd) {
      update({ cwd: ctx.cwd });
    }
    // Forzamos un refresh por si el tiempo elapsed cambió de minuto y
    // el render necesita actualizar el contador.
    refresh(ctx);
  });

  // ── session_shutdown ─────────────────────────────────────────────────
  pi.on("session_shutdown", async () => {
    if (pollHandle) {
      clearInterval(pollHandle);
      pollHandle = null;
    }
    if (unsubscribe) {
      unsubscribe();
      unsubscribe = null;
    }
    reset();
  });
}

files.project:.pi/extensions/cortex-footer.ts:
/**
 * cortex-footer.ts — Footer "tablero Cortex" (T1) + título de terminal por rol (T4)
 *
 * Tanda TUI del overhaul UX. Dos cosas, ambas client-side (0 tokens de LLM):
 *
 *   T1 · Footer powerline SIEMPRE visible (ctx.ui.setFooter). Reemplaza el
 *        footer built-in con una línea compacta: rol/persona · MASTER/WORKER ·
 *        sesión + tiempo · peers + 📨cola · modelo · % contexto · rama git.
 *        Lee todo del singleton _cortex-state + el FooterDataProvider (rama
 *        git + statuses de otras extensiones) + el último ctx (getContextUsage).
 *
 *   T4 · Título de la pestaña de terminal por rol (ctx.ui.setTitle), para
 *        distinguir las pestañas de WezTerm de un vistazo: "Cortex · designer".
 *
 * Por qué una extensión aparte y no dentro del cockpit: el cockpit (F1) fue
 * arreglado con cuidado (causa raíz del STANDBY) y es lector PURO vía widget +
 * setStatus. setFooter REEMPLAZA el footer built-in que renderiza esos
 * setStatus, así que este footer rinde la info del singleton directamente y
 * además anexa los statuses de OTRAS extensiones (vía getExtensionStatuses)
 * para no perder nada. Si se desactiva esta extensión, el cockpit vuelve a su
 * status bar built-in sin cambios.
 *
 * NO toca lógica de coordinación ni llama tools. Render puro sobre estado.
 *
 * Uso: settings.json defaultExtensions: [..., ".pi/extensions/cortex-footer.ts"].
 */

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { truncateToWidth, visibleWidth } from "@mariozechner/pi-tui";
import { cortexState, subscribe } from "../lib/cortex-state";

// ── Helpers ──────────────────────────────────────────────────────────────

/** "12m" / "1h32m" / "47s" (igual que el cockpit). */
function formatDuration(ms: number): string {
  const s = Math.floor(ms / 1000);
  if (s < 60) return `${s}s`;
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m`;
  const h = Math.floor(m / 60);
  return `${h}h${m - h * 60}m`;
}

function shortSessionId(id: string): string {
  if (id.length <= 24) return id;
  return id.slice(0, 21) + "…";
}

/** Sólo el id del modelo (último segmento de "provider/id"), acortado. */
function shortModel(model: string | null): string | null {
  if (!model) return null;
  const id = model.includes("/") ? model.slice(model.lastIndexOf("/") + 1) : model;
  return id.length <= 22 ? id : id.slice(0, 21) + "…";
}

/** Etiqueta de rol para footer/título. */
function roleLabel(): string {
  if (cortexState.myRole) return cortexState.myRole;
  if (cortexState.activeAgentName === "cortex-sync") return "sync";
  if (cortexState.sessionId) return "standby";
  return "—";
}

// Keys de status que ya representamos en la powerline (no las dupliques al
// anexar getExtensionStatuses): las 3 del cockpit + la persona de system-select.
const OWN_STATUS_KEYS = new Set(["cortex-session", "cortex-role", "cortex-peers", "cortex-agent"]);

// ── Extensión ──────────────────────────────────────────────────────────────

export default function (pi: ExtensionAPI) {
  // Último ctx visto, para getContextUsage()/model desde el factory del footer
  // (que recibe (tui, theme, footerData) pero NO ctx).
  let lastCtx: any = null;
  let lastTitle = "";
  let unsubscribe: (() => void) | null = null;

  /** Construye la línea de la powerline. Devuelve string[] (1 línea), truncada. */
  function renderFooter(theme: any, footerData: any, width: number): string[] {
    const W = Math.max(20, Math.min(width || 80, 200));
    const SEP = theme.fg("dim", " ▏ ");
    const segs: string[] = [];

    // ── Standby (sin sesión) ──
    if (!cortexState.sessionId) {
      segs.push(theme.fg("muted", "⬡ Cortex") + theme.fg("dim", " · standby"));
    } else {
      // Rol + MASTER/WORKER
      const role = roleLabel();
      let mode = "";
      if (cortexState.myRole) {
        mode = cortexState.isMaster
          ? theme.fg("accent", " MASTER")
          : theme.fg("muted", " WORKER");
      }
      segs.push(theme.fg("accent", "⬡ " + role) + mode);

      // Sesión + tiempo
      const elapsed = cortexState.sessionOpenedAt
        ? formatDuration(Date.now() - cortexState.sessionOpenedAt)
        : "—";
      segs.push(
        theme.fg("text", shortSessionId(cortexState.sessionId)) +
          theme.fg("dim", " " + elapsed)
      );

      // Peers + cola de inbound
      const npeers = cortexState.peers.length;
      const mail =
        cortexState.inbound.length > 0
          ? theme.fg("warning", ` 📨${cortexState.inbound.length}`)
          : "";
      segs.push(theme.fg("text", `${npeers}p`) + mail);
    }

    // Modelo (T1): del último ctx, o del singleton (lo siembra el cockpit).
    const modelStr =
      shortModel(
        lastCtx?.model
          ? `${lastCtx.model.provider ?? "?"}/${lastCtx.model.id ?? "?"}`
          : cortexState.myModel
      ) ?? null;
    if (modelStr) segs.push(theme.fg("dim", modelStr));

    // % de contexto (T1): coloreado por umbral.
    try {
      const usage = lastCtx?.getContextUsage?.();
      if (usage && usage.percent != null) {
        const pct = Math.round(usage.percent);
        const color = pct >= 85 ? "error" : pct >= 70 ? "warning" : "dim";
        segs.push(theme.fg(color, `ctx ${pct}%`));
      }
    } catch {
      /* getContextUsage puede no estar disponible */
    }

    // Rama git (del FooterDataProvider).
    try {
      const branch = footerData?.getGitBranch?.();
      if (branch) segs.push(theme.fg("dim", "⎇ " + branch));
    } catch {
      /* sin git */
    }

    // Anexar statuses de OTRAS extensiones (no las que ya representamos), para
    // no perderlas al reemplazar el footer built-in.
    try {
      const statuses: ReadonlyMap<string, string> | undefined =
        footerData?.getExtensionStatuses?.();
      if (statuses) {
        for (const [key, text] of statuses) {
          if (OWN_STATUS_KEYS.has(key)) continue;
          if (text && text.trim()) segs.push(theme.fg("dim", text));
        }
      }
    } catch {
      /* best-effort */
    }

    const line = segs.join(SEP);
    return [visibleWidth(line) > W ? truncateToWidth(line, W) : line];
  }

  /** (Re)aplica el footer y el título. */
  function apply(ctx: any): void {
    lastCtx = ctx;
    try {
      ctx.ui.setFooter((_tui: any, theme: any, footerData: any) => ({
        render(width: number): string[] {
          return renderFooter(theme, footerData, width);
        },
        invalidate() {
          /* render puro sobre cortexState */
        },
        dispose() {
          /* nada que limpiar */
        },
      }));
    } catch {
      /* si setFooter no está disponible en este modo (print/rpc), no pasa nada */
    }

    // T4 · título de terminal por rol (sólo si cambió, para no spammear).
    try {
      const title = `Cortex · ${roleLabel()}`;
      if (title !== lastTitle) {
        ctx.ui.setTitle(title);
        lastTitle = title;
      }
    } catch {
      /* setTitle puede no estar disponible */
    }
  }

  pi.on("session_start", async (_event, ctx) => {
    lastCtx = ctx;
    // Re-aplicar el footer cuando el estado cambie (peers, rol, cola, etc.).
    unsubscribe = subscribe(() => {
      if (lastCtx) apply(lastCtx);
    });
    apply(ctx);
  });

  // Refrescar por turno: actualiza % de contexto, tiempo y modelo aunque el
  // singleton no haya mutado.
  pi.on("turn_end", async (_event, ctx) => {
    apply(ctx);
  });
  pi.on("turn_start", async (_event, ctx) => {
    lastCtx = ctx;
  });

  pi.on("session_shutdown", async () => {
    if (unsubscribe) {
      unsubscribe();
      unsubscribe = null;
    }
  });
}

files.project:.pi/extensions/cortex-mcp.ts:
/**
 * cortex-mcp — Adaptador MCP para Pi
 *
 * Pi no tiene soporte nativo de MCP. Esta extensión lo implementa:
 *   1. Lee .pi/mcp.json al arrancar (formato idéntico a Claude Code)
 *   2. Lanza cada servidor MCP como subproceso stdio
 *   3. Registra las tools de cada servidor como tools de Pi con el prefijo mcp_<server>_<tool>
 *   4. Gestiona el ciclo de vida: startup, keep-alive, shutdown limpio
 *
 * Formato de .pi/mcp.json:
 * {
 *   "mcpServers": {
 *     "cortex-mcp": {
 *       "command": "python",
 *       "args": ["-m", "cortex.mcp.server"],
 *       "cwd": ".",                          ← opcional, relativo al proyecto
 *       "env": { "CORTEX_CONFIG_PATH": "config.yaml" }
 *     }
 *   }
 * }
 *
 * Variables disponibles en cwd/args/env:
 *   ${cwd}  → directorio del proyecto
 *
 * Comandos:
 *   /mcp          → muestra estado de todos los servidores y sus tools
 *   /mcp-restart  → reinicia todos los servidores (útil tras cambios en el server)
 *
 * Uso: pi -e .pi/extensions/cortex-mcp.ts
 * (o agregarlo a settings.json → extensions)
 */

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { Text } from "@mariozechner/pi-tui";
import { Type } from "@sinclair/typebox";
import { readFileSync, existsSync } from "fs";
import { join, resolve } from "path";
import { spawn, ChildProcess, execFileSync } from "child_process";
import { homedir } from "os";

// ── MCP Protocol types (subset) ────────────────────────────────────────────

interface McpJsonRpc {
  jsonrpc: "2.0";
  id?: number | string;
  method?: string;
  params?: any;
  result?: any;
  error?: { code: number; message: string; data?: any };
}

interface McpTool {
  name: string;
  description?: string;
  inputSchema: {
    type: "object";
    properties?: Record<string, any>;
    required?: string[];
  };
}

interface McpServerConfig {
  command: string;
  args?: string[];
  cwd?: string;
  env?: Record<string, string>;
}

interface McpConfig {
  mcpServers: Record<string, McpServerConfig>;
}

// ── Pipx Python resolver ──────────────────────────────────────────────────

/**
 * Dado el nombre del paquete instalado con pipx (ej: "cortex"),
 * devuelve la ruta absoluta al python.exe dentro de su venv.
 *
 * Estrategia en orden:
 *  1. PIPX_HOME env var si está definida
 *  2. Ruta estándar de Windows: %LOCALAPPDATA%\pipx\pipx\venvs
 *  3. Ruta estándar Unix:       ~/.local/pipx/venvs  o  ~/.local/share/pipx/venvs
 *  4. Fallback: "python" del PATH (puede no tener el paquete)
 */
function resolvePipxPython(packageName: string): string {
  const isWin = process.platform === "win32";
  const pythonBin = isWin ? "Scripts\\python.exe" : "bin/python";
  const home = homedir();
  const candidates: string[] = [];

  // 1. PIPX_HOME env var explícita
  if (process.env.PIPX_HOME) {
    candidates.push(join(process.env.PIPX_HOME, "venvs", packageName, pythonBin));
  }

  // 2. Preguntar a pipx directamente → obtiene PIPX_LOCAL_VENVS real
  try {
    const venvs = execFileSync("pipx", ["environment", "--value", "PIPX_LOCAL_VENVS"], {
      encoding: "utf-8",
      timeout: 5000,
    }).trim();
    if (venvs) candidates.push(join(venvs, packageName, pythonBin));
  } catch {}

  // 3. Rutas derivadas por plataforma
  if (isWin) {
    // pipx usa %USERPROFILE%\pipx cuando PIPX_HOME no está definido
    candidates.push(join(home, "pipx", "venvs", packageName, pythonBin));
    const localAppData = process.env.LOCALAPPDATA ?? join(home, "AppData", "Local");
    candidates.push(join(localAppData, "pipx", "pipx", "venvs", packageName, pythonBin));
    candidates.push(join(localAppData, "pipx", "venvs", packageName, pythonBin));
  } else {
    candidates.push(join(home, ".local", "pipx", "venvs", packageName, pythonBin));
    candidates.push(join(home, ".local", "share", "pipx", "venvs", packageName, pythonBin));
    candidates.push(join(home, "pipx", "venvs", packageName, pythonBin));
  }

  for (const candidate of candidates) {
    if (existsSync(candidate)) return candidate;
  }

  return isWin ? "python" : "python3";
}

// ── Pipx CLI binary resolver ──────────────────────────────────────────────

/**
 * Resuelve el ejecutable CLI (ej: cortex.exe) dentro del venv de pipx,
 * a diferencia de resolvePipxPython que resuelve python.exe.
 */
function resolvePipxBin(packageName: string, binName: string): string {
  const isWin = process.platform === "win32";
  const bin = isWin ? `${binName}.exe` : binName;
  const home = homedir();
  const candidates: string[] = [];

  if (process.env.PIPX_HOME) {
    const scriptDir = isWin ? "Scripts" : "bin";
    candidates.push(join(process.env.PIPX_HOME, "venvs", packageName, scriptDir, bin));
  }

  try {
    const venvs = execFileSync("pipx", ["environment", "--value", "PIPX_LOCAL_VENVS"], {
      encoding: "utf-8", timeout: 5000,
    }).trim();
    if (venvs) {
      const scriptDir = isWin ? "Scripts" : "bin";
      candidates.push(join(venvs, packageName, scriptDir, bin));
    }
  } catch {}

  if (isWin) {
    candidates.push(join(home, "pipx", "venvs", packageName, "Scripts", bin));
    const localAppData = process.env.LOCALAPPDATA ?? join(home, "AppData", "Local");
    candidates.push(join(localAppData, "pipx", "pipx", "venvs", packageName, "Scripts", bin));
  } else {
    candidates.push(join(home, ".local", "pipx", "venvs", packageName, "bin", bin));
    candidates.push(join(home, "pipx", "venvs", packageName, "bin", bin));
  }

  for (const candidate of candidates) {
    if (existsSync(candidate)) return candidate;
  }

  // Fallback: el bin en el PATH global (pipx lo instala en ~/.local/bin)
  return bin;
}

// ── MCP Client (stdio transport) ────────────────────────────────────────────

class McpClient {
  private proc: ChildProcess | null = null;
  public lastStderr: string = "";
  private pending = new Map<number, { resolve: (r: any) => void; reject: (e: any) => void }>();
  private nextId = 1;
  private buf = "";
  public tools: McpTool[] = [];
  public status: "stopped" | "starting" | "ready" | "error" = "stopped";
  public error: string = "";

  constructor(
    public readonly name: string,
    private readonly cfg: McpServerConfig,
    private readonly cwd: string
  ) {}

  private interpolate(s: string): string {
    return s.replace(/\$\{cwd\}/g, this.cwd);
  }

  async start(): Promise<void> {
    this.status = "starting";
    this.error = "";

    const serverCwd = this.cfg.cwd
      ? resolve(this.cwd, this.interpolate(this.cfg.cwd))
      : this.cwd;

    const env: Record<string, string> = {
      ...process.env as Record<string, string>,
      ...Object.fromEntries(
        Object.entries(this.cfg.env ?? {}).map(([k, v]) => [k, this.interpolate(v)])
      ),
    };

    const args = (this.cfg.args ?? []).map((a) => this.interpolate(a));

    // Resuelve el comando:
    //   "pipx:<paquete>"     → python.exe del venv pipx de ese paquete
    //   "pipx-bin:<paquete>" → ejecutable CLI del venv pipx (ej: cortex.exe)
    //   "python" o "python3" → intenta auto-detectar el paquete desde los args
    let command = this.interpolate(this.cfg.command);
    if (command.startsWith("pipx-bin:")) {
      // Sintaxis: "pipx-bin:<package>:<binname>"
      // Ejemplo:  "pipx-bin:cortex-memory:cortex" → cortex.exe en el venv de cortex-memory
      const parts = command.slice(9).split(":");
      const pkg = parts[0].trim();
      const binName = (parts[1] ?? "").trim() || pkg.split("-")[0];
      command = resolvePipxBin(pkg, binName);
    } else if (command.startsWith("pipx:")) {
      const pkg = command.slice(5).trim();
      command = resolvePipxPython(pkg);
    } else if (command === "python" || command === "python3") {
      const mIdx = args.indexOf("-m");
      if (mIdx !== -1 && args[mIdx + 1]) {
        const pkg = args[mIdx + 1].split(".")[0];
        const resolved = resolvePipxPython(pkg);
        if (resolved !== "python" && resolved !== "python3") {
          command = resolved;
        }
      }
    }


    try {
      this.proc = spawn(command, args, {
        cwd: serverCwd,
        env,
        stdio: ["pipe", "pipe", "pipe"],
      });

      let stderrBuf = "";
      this.proc.stderr?.setEncoding("utf-8");
      this.proc.stderr?.on("data", (d: string) => {
        stderrBuf += d;
        this.lastStderr = (this.lastStderr + "\n" + stderrBuf).slice(-2000);
      });

      this.proc.stdout?.setEncoding("utf-8");
      this.proc.stdout?.on("data", (chunk: string) => {
        this.buf += chunk;
        const lines = this.buf.split("\n");
        this.buf = lines.pop() ?? "";
        for (const line of lines) {
          const trimmed = line.trim();
          if (!trimmed) continue;
          try {
            const msg: McpJsonRpc = JSON.parse(trimmed);
            if (msg.id !== undefined) {
              const p = this.pending.get(msg.id as number);
              if (p) {
                this.pending.delete(msg.id as number);
                if (msg.error) p.reject(new Error(msg.error.message));
                else p.resolve(msg.result);
              }
            }
          } catch {}
        }
      });

      this.proc.on("exit", (code) => {
        // Espera un tick para que los datos de stderr lleguen antes de marcar el error
        setTimeout(() => {
          if (this.status !== "stopped") {
            this.status = "error";
            const hint = this.lastStderr
              ? `\n  stderr: ${this.lastStderr.split("\n").filter(l => l.trim()).slice(-5).join(" | ").slice(0, 400)}`
              : " (sin output en stderr — ¿está el servidor MCP instalado?)";
            this.error = `Proceso terminó con código ${code}${hint}`;
          }
          for (const p of this.pending.values()) p.reject(new Error(this.error || "MCP server exited"));
          this.pending.clear();
        }, 100);
      });

      this.proc.on("error", (err) => {
        this.status = "error";
        this.error = err.message;
      });

      // Handshake: initialize → initialized → tools/list
      await this.send("initialize", {
        protocolVersion: "2024-11-05",
        capabilities: {},
        clientInfo: { name: "pi-cortex-mcp", version: "1.0.0" },
      });

      this.sendNotification("notifications/initialized", {});

      const result = await this.send("tools/list", {});
      this.tools = result?.tools ?? [];
      this.status = "ready";
    } catch (err: any) {
      // Espera 150ms para que el evento stderr llegue antes del exit
      await new Promise(r => setTimeout(r, 150));
      this.status = "error";
      const baseMsg = err.message ?? String(err);
      const stderrLines = this.lastStderr
        .split("\n").filter((l: string) => l.trim()).slice(-8).join("\n");
      this.error = stderrLines
        ? `${baseMsg}\nstderr:\n${stderrLines}`
        : `${baseMsg}\n(sin stderr — verificá que .venv esté activo y cortex.mcp.server instalado)`;
      throw new Error(this.error);
    }
  }

  private send(method: string, params: any): Promise<any> {
    return new Promise((resolve, reject) => {
      if (!this.proc?.stdin?.writable) {
        reject(new Error("MCP server not running"));
        return;
      }
      const id = this.nextId++;
      const msg: McpJsonRpc = { jsonrpc: "2.0", id, method, params };
      this.pending.set(id, { resolve, reject });

      // Timeout de 30s por request
      const timer = setTimeout(() => {
        this.pending.delete(id);
        reject(new Error(`MCP request timed out: ${method}`));
      }, 30_000);
      this.pending.get(id)!.resolve = (r) => { clearTimeout(timer); resolve(r); };
      this.pending.get(id)!.reject = (e) => { clearTimeout(timer); reject(e); };

      this.proc!.stdin!.write(JSON.stringify(msg) + "\n");
    });
  }

  private sendNotification(method: string, params: any) {
    if (!this.proc?.stdin?.writable) return;
    const msg: McpJsonRpc = { jsonrpc: "2.0", method, params };
    this.proc.stdin.write(JSON.stringify(msg) + "\n");
  }

  async callTool(toolName: string, args: Record<string, any>): Promise<string> {
    const result = await this.send("tools/call", { name: toolName, arguments: args });
    // MCP tools/call → { content: [{type, text}] }
    if (Array.isArray(result?.content)) {
      return result.content
        .filter((c: any) => c.type === "text")
        .map((c: any) => c.text)
        .join("\n");
    }
    return JSON.stringify(result);
  }

  stop() {
    this.status = "stopped";
    try { this.proc?.stdin?.end(); } catch {}
    try { this.proc?.kill(); } catch {}
    this.proc = null;
    this.pending.clear();
  }
}

// ── Extension ──────────────────────────────────────────────────────────────

export default function (pi: ExtensionAPI) {
  const clients = new Map<string, McpClient>();

  // Renderer para los mensajes de status de esta extensión
  pi.registerMessageRenderer("cortex-mcp", (message, _options, theme) => {
    const content = typeof message.content === "string" ? message.content : "";
    return new Text(theme.fg("cyan", "⬡ mcp: ") + content, 0, 0);
  });

  // ── Carga la config y levanta los servidores ───────────────────────────
  async function loadAndStart(cwd: string, ctx: any) {
    // Primero intenta .pi/mcp.json; si no existe, intenta pi-mcp-adapter.json en la raíz
    const candidates = [
      join(cwd, ".pi", "mcp.json"),
      join(cwd, "pi-mcp-adapter.json"),
    ];

    let config: McpConfig | null = null;
    let configPath = "";

    for (const candidate of candidates) {
      if (existsSync(candidate)) {
        try {
          config = JSON.parse(readFileSync(candidate, "utf-8")) as McpConfig;
          configPath = candidate;
          break;
        } catch (err: any) {
          ctx.ui.notify(`⚠ MCP: error leyendo ${candidate}: ${err.message}`, "warning");
        }
      }
    }

    if (!config || !config.mcpServers || Object.keys(config.mcpServers).length === 0
        || (config as any)._disabled === true) {
      // Sin servidores activos (o deshabilitado intencionalmente) → silencio
      return;
    }

    ctx.ui.notify(`⬡ MCP: levantando servidores desde ${configPath}…`, "info");

    for (const [name, cfg] of Object.entries(config.mcpServers)) {
      const client = new McpClient(name, cfg, cwd);
      clients.set(name, client);

      try {
        await client.start();
        ctx.ui.notify(`✓ MCP: "${name}" listo — ${client.tools.length} tool(s)`, "success");

        // Registra cada tool del servidor como tool de Pi
        for (const tool of client.tools) {
          // Naming: si el nombre completo resultante tendría el segmento "cortex" duplicado
          // (mcp_cortex_cortex_search), lo colapsamos a cortex_search directamente.
          const serverSlug = name.replace(/-/g, "_");
          const rawName = `mcp_${serverSlug}_${tool.name}`;
          // Detecta duplicado: mcp_cortex_cortex_* → cortex_*
          const dupPattern = new RegExp(`^mcp_${serverSlug}_${serverSlug}_`);
          const piToolName = dupPattern.test(rawName)
            ? rawName.replace(`mcp_${serverSlug}_`, "")
            : rawName;
          const schema = tool.inputSchema?.properties ?? {};

          // Construye el schema Typebox equivalente al inputSchema del MCP tool
          const tbProps: Record<string, any> = {};
          const required: string[] = tool.inputSchema?.required ?? [];

          for (const [key, def] of Object.entries(schema)) {
            const d = def as any;
            if (d.type === "string") {
              tbProps[key] = required.includes(key)
                ? Type.String({ description: d.description ?? key })
                : Type.Optional(Type.String({ description: d.description ?? key }));
            } else if (d.type === "number" || d.type === "integer") {
              tbProps[key] = required.includes(key)
                ? Type.Number({ description: d.description ?? key })
                : Type.Optional(Type.Number({ description: d.description ?? key }));
            } else if (d.type === "boolean") {
              tbProps[key] = required.includes(key)
                ? Type.Boolean({ description: d.description ?? key })
                : Type.Optional(Type.Boolean({ description: d.description ?? key }));
            } else {
              // Tipos complejos (array, object) → string serializado
              tbProps[key] = Type.Optional(Type.String({ description: `(JSON) ${d.description ?? key}` }));
            }
          }

          pi.registerTool({
            name: piToolName,
            label: `MCP: ${name}/${tool.name}`,
            description: tool.description ?? `MCP tool ${tool.name} del servidor ${name}`,
            parameters: Type.Object(tbProps),
            async execute(_toolCallId: string, params: Record<string, any>, _signal: AbortSignal) {
              // Deserializa strings JSON para tipos complejos
              const callArgs: Record<string, any> = {};
              for (const [k, v] of Object.entries(params)) {
                if (v === undefined || v === null) continue;
                if (typeof v === "string") {
                  try { callArgs[k] = JSON.parse(v); } catch { callArgs[k] = v; }
                } else {
                  callArgs[k] = v;
                }
              }

              try {
                const result = await client.callTool(tool.name, callArgs);
                return {
                  content: [{ type: "text" as const, text: result }],
                  details: { server: name, tool: tool.name, args: callArgs },
                };
              } catch (err: any) {
                return {
                  content: [{ type: "text" as const, text: `Error MCP: ${err.message}` }],
                  details: { error: err.message },
                };
              }
            },
          });
        }
      } catch (err: any) {
        const clientErr = clients.get(name);
        const stderrInfo = clientErr?.lastStderr
          ? `\nstderr:\n${clientErr.lastStderr.split("\n").slice(-8).join("\n")}`
          : "";
        ctx.ui.notify(
          `⚠ MCP: "${name}" falló al iniciar: ${err.message}${stderrInfo}`,
          "warning"
        );
      }
    }
  }

  // ── Arranca al inicio de sesión ────────────────────────────────────────
  pi.on("session_start", async (_event, ctx) => {
    await loadAndStart(ctx.cwd, ctx);
  });

  // ── Shutdown limpio al cerrar ──────────────────────────────────────────
  pi.on("session_shutdown", async () => {
    for (const client of clients.values()) client.stop();
    clients.clear();
  });

  // ── /mcp — estado de servidores ────────────────────────────────────────
  pi.registerCommand("mcp", {
    description: "Muestra el estado de los servidores MCP de Cortex",
    handler(_args: string, ctx: any) {
      if (clients.size === 0) {
        ctx.ui.notify("Sin servidores MCP activos. Verificá .pi/mcp.json", "warning");
        return;
      }

      const lines = [...clients.entries()].map(([name, client]) => {
        const icon =
          client.status === "ready" ? "✓" :
          client.status === "error" ? "✗" :
          client.status === "starting" ? "◉" : "○";

        const toolList = client.tools.length > 0
          ? client.tools.map(t => `mcp_${name.replace(/-/g, "_")}_${t.name}`).join(", ")
          : "(sin tools)";

        const errorPart = client.error ? `\n  Error: ${client.error}` : "";
        const stderrPart = client.lastStderr
          ? `\n  Stderr (últimas líneas):\n${client.lastStderr.split("\n").filter((l: string) => l.trim()).slice(-6).map((l: string) => "    " + l).join("\n")}`
          : "";
        return `${icon} ${name} [${client.status}]\n  Tools: ${toolList}${errorPart}${stderrPart}`;
      });

      pi.sendMessage({
        customType: "cortex-mcp",
        content: `Servidores MCP:\n\n${lines.join("\n\n")}`,
        display: true,
      });
    },
  });

  // ── /mcp-debug — muestra rutas resueltas sin levantar el servidor ───────
  pi.registerCommand("mcp-debug", {
    description: "Muestra las rutas de Python que la extensión usaría para cada servidor MCP",
    handler(_args: string, ctx: any) {
      const cwd = ctx.cwd;
      const candidates = [
        join(cwd, ".pi", "mcp.json"),
        join(cwd, "pi-mcp-adapter.json"),
      ];

      let config: McpConfig | null = null;
      let configPath = "(no encontrado)";
      for (const c of candidates) {
        if (existsSync(c)) {
          try { config = JSON.parse(readFileSync(c, "utf-8")) as McpConfig; configPath = c; break; } catch {}
        }
      }

      if (!config) {
        ctx.ui.notify("⚠ No se encontró .pi/mcp.json ni pi-mcp-adapter.json", "warning");
        return;
      }

      const isWin = process.platform === "win32";
      const lines = [`Config: ${configPath}`, ""];

      for (const [name, cfg] of Object.entries(config.mcpServers)) {
        let command = cfg.command;
        let resolved = command;

        if (command.startsWith("pipx:")) {
          const pkg = command.slice(5).trim();
          resolved = resolvePipxPython(pkg);
        } else if (command === "python" || command === "python3") {
          const args = cfg.args ?? [];
          const mIdx = args.indexOf("-m");
          if (mIdx !== -1 && args[mIdx + 1]) {
            const pkg = args[mIdx + 1].split(".")[0];
            const r = resolvePipxPython(pkg);
            if (r !== "python" && r !== "python3") resolved = r;
          }
        }

        const exists = existsSync(resolved);
        const icon = exists ? "✓" : (resolved === command ? "?" : "✗");
        lines.push(`${icon} Servidor: ${name}`);
        lines.push(`  command en config : ${command}`);
        lines.push(`  python resuelto   : ${resolved}`);
        lines.push(`  existe en disco   : ${exists ? "sí" : "NO — ruta incorrecta"}`);
        lines.push(`  platform          : ${process.platform}`);
        if (!exists && !isWin) {
          lines.push(`  sugerencia: corré 'pipx environment' en tu terminal para ver PIPX_LOCAL_VENVS`);
        }
        if (!exists && isWin) {
          const local = process.env.LOCALAPPDATA ?? "no definido";
          lines.push(`  LOCALAPPDATA: ${local}`);
        }
        lines.push("");
      }

      pi.sendMessage({
        customType: "cortex-mcp",
        content: lines.join("\n"),
        display: true,
      });
    },
  });

  // ── /mcp-restart — reinicia todos los servidores ──────────────────────
  pi.registerCommand("mcp-restart", {
    description: "Reinicia todos los servidores MCP de Cortex",
    async handler(_args: string, ctx: any) {
      ctx.ui.notify("⬡ MCP: reiniciando servidores…", "info");
      for (const client of clients.values()) client.stop();
      clients.clear();
      await loadAndStart(ctx.cwd, ctx);
    },
  });
}

