/**
 * cortex-team.ts — Auto-spawn portable de terminales para Cortex Pi 2.5+net
 *
 * F5 del overhaul UX (ver docs/multi-ide-mcp-hardening/PI-COCKPIT-UX/).
 *
 * Registra el slash command ``/cortex-team`` que:
 *
 *   1. Verifica que somos master (sólo el master puede spawnear).
 *   2. Filtra los roles ya conectados a la red.
 *   3. Muestra presets útiles (Deep Track full, Audit pair, etc.).
 *   4. Spawnea las terminales nuevas con detección de OS y terminal
 *      multiplexer disponible.
 *   5. Si la detección falla, copia los comandos al clipboard como
 *      fallback (universal).
 *   6. Trackea las hijas spawneadas en ``.pi/agent-sessions/team.json``.
 *
 * Estrategia de detección de terminal:
 *
 *   1. Terminal del usuario por env (cross-platform): WezTerm
 *      (WEZTERM_PANE / WEZTERM_EXECUTABLE → ``wezterm cli spawn``).
 *   2. Default del SO:
 *        Windows : wt.exe (Windows Terminal) → fallback ``start cmd``.
 *        Linux   : tmux (si TMUX env) → alacritty → kitty →
 *                  gnome-terminal → konsole → xterm.
 *        macOS   : osascript para Terminal.app.
 *   3. clipboard fallback (universal).
 *
 * Cada terminal hija arranca con ``pi`` (que carga el stack UX completo de
 * settings.json: cockpit/net/panel/etc.) y el rol forzado vía la env var
 * CORTEX_NET_ROLE. NO usa ``just`` (no todos lo tienen instalado).
 *
 * Coordinated shutdown: NO implementado en F5. Si el master cierra la
 * sesión, las hijas siguen funcionando pero el cortex-net del peer
 * detecta el cambio del session.lock (vía polling de F1) y la red
 * queda en standby. Iteración futura: flag ``shutdown: true`` en
 * team.json que las hijas chequean en turn_end.
 */

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { spawn, spawnSync, execSync } from "child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "fs";
import { join } from "path";
// Bugfix mayo 2026: import desde .pi/lib/ (ver cortex-cockpit.ts y
// docs/multi-ide-mcp-hardening/PI-COCKPIT-UX/README.md § 8).
import {
  cortexState,
  agentForRole,
  registerTeamActions,
  type CortexRole,
} from "../lib/cortex-state";

// ── Detección de comandos disponibles ───────────────────────────────────────

/**
 * Chequea si ``cmd`` existe en el PATH. Robusto: usa ``where`` en
 * Windows y ``which`` en *nix; cualquier error (no encontrado, permiso
 * denegado, etc.) devuelve false.
 */
function commandExists(cmd: string): boolean {
  try {
    if (process.platform === "win32") {
      execSync(`where ${cmd}`, { stdio: "ignore", windowsHide: true });
    } else {
      execSync(`which ${cmd}`, { stdio: "ignore" });
    }
    return true;
  } catch {
    return false;
  }
}

/**
 * Copia ``text`` al clipboard del SO. Usa ``clip`` en Windows,
 * ``pbcopy`` en macOS, ``xclip``/``xsel`` en Linux. Devuelve true si
 * alguna estrategia funcionó.
 */
function copyToClipboard(text: string): boolean {
  const platform = process.platform;
  const candidates: Array<{ cmd: string; args?: string[] }> =
    platform === "win32"
      ? [{ cmd: "clip" }]
      : platform === "darwin"
      ? [{ cmd: "pbcopy" }]
      : [
          { cmd: "xclip", args: ["-selection", "clipboard"] },
          { cmd: "xsel", args: ["--clipboard", "--input"] },
          { cmd: "wl-copy" }, // Wayland
        ];

  for (const c of candidates) {
    if (!commandExists(c.cmd)) continue;
    try {
      const proc = spawn(c.cmd, c.args ?? [], { stdio: ["pipe", "ignore", "ignore"] });
      proc.stdin.write(text);
      proc.stdin.end();
      return true;
    } catch {
      /* probar siguiente */
    }
  }
  return false;
}

// ── Spawn de terminales por OS ──────────────────────────────────────────────

interface SpawnResult {
  success: boolean;
  /** Comando manual a copiar/pegar si success === false. */
  fallback?: string;
  /** Mecanismo detectado/usado. Útil para diagnóstico. */
  mechanism?: string;
  /** Nota de diagnóstico (p.ej. el error real si wezterm falló). */
  note?: string;
}

/**
 * Resuelve el binario CLI de WezTerm (``wezterm``/``wezterm.exe``), que es el
 * que tiene el subcomando ``cli``. OJO: ``WEZTERM_EXECUTABLE`` suele apuntar a
 * ``wezterm-gui(.exe)``, que NO maneja ``cli spawn`` — por eso preferimos
 * ``wezterm(.exe)`` del mismo directorio y, si no, el del PATH.
 */
function weztermCli(): string {
  const cliName = process.platform === "win32" ? "wezterm.exe" : "wezterm";
  const exe = process.env.WEZTERM_EXECUTABLE;
  if (exe) {
    const dir = exe.replace(/[\\/][^\\/]*$/, "");
    const candidate = join(dir, cliName);
    if (existsSync(candidate)) return candidate;
  }
  return cliName; // del PATH
}

/**
 * Spawnea una terminal nueva en ``cwd`` y le hace correr ``pi`` con
 * ``CORTEX_NET_ROLE=<role>``. Cross-platform con fallback elegante.
 *
 * Devuelve ``{success: true, mechanism}`` si funcionó, o
 * ``{success: false, fallback}`` con el comando para que el usuario lo
 * pegue manualmente.
 */
function spawnTerminal(cwd: string, role: CortexRole): SpawnResult {
  const platform = process.platform;
  const isWin = platform === "win32";
  // Bugfix may 2026: lanzamos `pi` directamente (que carga
  // settings.json defaultExtensions = stack UX completo) con el rol forzado
  // por env var. Antes corría `just role-<role>`, que (a) requería tener
  // `just` instalado y (b) cargaba un stack reducido SIN cockpit/UX.
  // cortex-net.resolveRole() respeta CORTEX_NET_ROLE.
  // CORTEX_NET_ROLE: lo lee cortex-net para el rol de red (registro).
  // CORTEX_AGENT: lo lee system-select para auto-activar la PERSONA Pi del
  // rol en la hija (sino el peer queda con "agent: (ninguno)" y persona
  // default en vez de, p.ej., documenter).
  const agent = agentForRole(role);
  const winCmd = `$env:CORTEX_NET_ROLE='${role}'; $env:CORTEX_AGENT='${agent}'; pi`; // PowerShell
  const cmdCmd = `set "CORTEX_NET_ROLE=${role}" && set "CORTEX_AGENT=${agent}" && pi`; // cmd.exe
  const nixCmd = `CORTEX_NET_ROLE=${role} CORTEX_AGENT=${agent} pi`; // bash
  // Comando seguro para PEGAR a mano (clipboard fallback). PowerShell-safe
  // en Windows (cd /d y && fallan en PowerShell) — fix del hallazgo #14.
  const pasteCmd = isWin
    ? `Set-Location '${cwd}'; $env:CORTEX_NET_ROLE='${role}'; $env:CORTEX_AGENT='${agent}'; pi`
    : `cd '${cwd}' && CORTEX_NET_ROLE=${role} CORTEX_AGENT=${agent} pi`;

  // ── Terminal del usuario, detectada por env (cross-platform) ──
  // Respeta la terminal REAL (p.ej. WezTerm con tu config gráfica) en vez de
  // abrir la default del SO. WezTerm setea WEZTERM_PANE / WEZTERM_EXECUTABLE
  // en cada panel y expone `wezterm cli spawn`, que abre una pestaña nueva en
  // tu ventana actual usando tu configuración.
  if (process.env.WEZTERM_PANE || process.env.WEZTERM_EXECUTABLE) {
    const wez = weztermCli();
    const wezArgs = isWin
      ? ["cli", "spawn", "--cwd", cwd, "--", "powershell", "-NoExit", "-Command", winCmd]
      : ["cli", "spawn", "--cwd", cwd, "--", "bash", "-lc", `${nixCmd}; exec bash`];
    // spawnSync (NO async): así sabemos DE VERDAD si abrió la pestaña.
    // `wezterm cli spawn` es rápido — le pide al mux y sale con el pane id.
    const r = spawnSync(wez, wezArgs, {
      stdio: ["ignore", "ignore", "pipe"],
      windowsHide: true,
      encoding: "utf-8",
    });
    if (!r.error && r.status === 0) {
      return { success: true, mechanism: "wezterm" };
    }
    // Falló de verdad → devolvemos el error REAL (antes reportaba "ok"
    // optimista aunque no abriera nada). El usuario ve el motivo + el
    // comando para pegar a mano.
    const why = (
      r.error?.message ||
      (typeof r.stderr === "string" ? r.stderr : "") ||
      `exit ${r.status}`
    )
      .toString()
      .trim()
      .slice(0, 300);
    return {
      success: false,
      mechanism: "wezterm",
      fallback: pasteCmd,
      note: `wezterm cli falló (bin: ${wez}): ${why}`,
    };
  }

  // ── Windows (terminal default del SO) ──
  if (platform === "win32") {
    if (commandExists("wt")) {
      // Windows Terminal: nueva tab en la ventana actual.
      try {
        spawn(
          "wt.exe",
          [
            "-w",
            "0",
            "nt",
            "--title",
            role,
            "-d",
            cwd,
            "powershell",
            "-NoExit",
            "-Command",
            winCmd,
          ],
          { detached: true, stdio: "ignore", windowsHide: false }
        ).unref();
        return { success: true, mechanism: "windows-terminal" };
      } catch {
        /* caer a cmd start */
      }
    }
    // Fallback: cmd.exe start abre nueva ventana cmd.
    try {
      spawn(
        "cmd.exe",
        ["/c", "start", "cmd.exe", "/K", `cd /d "${cwd}" && ${cmdCmd}`],
        { detached: true, stdio: "ignore", windowsHide: false }
      ).unref();
      return { success: true, mechanism: "cmd-start" };
    } catch {
      return {
        success: false,
        fallback: pasteCmd,
      };
    }
  }

  // ── macOS ──
  if (platform === "darwin") {
    // osascript abre Terminal.app y le manda el comando.
    const script =
      `tell application "Terminal" to do script "cd '${cwd.replace(
        /'/g,
        "'\\''"
      )}' && ${nixCmd}"`;
    try {
      spawn("osascript", ["-e", script], {
        detached: true,
        stdio: "ignore",
      }).unref();
      return { success: true, mechanism: "osascript-terminal" };
    } catch {
      return {
        success: false,
        fallback: pasteCmd,
      };
    }
  }

  // ── Linux / otro Unix ──
  // Preferimos tmux si ya estamos dentro de una sesión.
  if (process.env.TMUX) {
    try {
      spawn(
        "tmux",
        ["split-window", "-h", "-c", cwd, nixCmd],
        { detached: true, stdio: "ignore" }
      ).unref();
      return { success: true, mechanism: "tmux-split" };
    } catch {
      /* caer a otros */
    }
  }

  // Terminales gráficas (en orden de preferencia).
  const linuxTerminals: Array<{ cmd: string; argsFn: () => string[] }> = [
    {
      cmd: "alacritty",
      argsFn: () => [
        "--working-directory",
        cwd,
        "-t",
        role,
        "-e",
        "bash",
        "-c",
        `${nixCmd}; exec bash`,
      ],
    },
    {
      cmd: "kitty",
      argsFn: () => [
        "--directory",
        cwd,
        "--title",
        role,
        "bash",
        "-c",
        `${nixCmd}; exec bash`,
      ],
    },
    {
      cmd: "gnome-terminal",
      argsFn: () => [
        "--tab",
        "--title",
        role,
        "--working-directory",
        cwd,
        "--",
        "bash",
        "-c",
        `${nixCmd}; exec bash`,
      ],
    },
    {
      cmd: "konsole",
      argsFn: () => [
        "--workdir",
        cwd,
        "-e",
        "bash",
        "-c",
        `${nixCmd}; exec bash`,
      ],
    },
    {
      cmd: "xterm",
      argsFn: () => [
        "-T",
        role,
        "-e",
        `cd '${cwd}' && ${nixCmd}; exec bash`,
      ],
    },
  ];

  for (const term of linuxTerminals) {
    if (!commandExists(term.cmd)) continue;
    try {
      spawn(term.cmd, term.argsFn(), {
        detached: true,
        stdio: "ignore",
      }).unref();
      return { success: true, mechanism: term.cmd };
    } catch {
      /* probar siguiente */
    }
  }

  // Ninguna terminal detectada: fallback a clipboard.
  return {
    success: false,
    fallback: pasteCmd,
  };
}

// ── Tracking en team.json ──────────────────────────────────────────────────

interface TeamEntry {
  master_pid: number;
  session_id: string;
  cwd: string;
  spawned: Array<{
    role: CortexRole;
    spawned_at: string;
    mechanism: string;
  }>;
  /** Coordinated shutdown: el master lo setea al cerrar (reason quit). Los
   *  workers de la MISMA session_id lo detectan por polling y avisan. */
  shutdown?: boolean;
  shutdown_at?: string;
}

function teamFilePath(cwd: string): string {
  return join(cwd, ".pi", "agent-sessions", "team.json");
}

function readTeamFile(cwd: string): TeamEntry | null {
  const p = teamFilePath(cwd);
  if (!existsSync(p)) return null;
  try {
    return JSON.parse(readFileSync(p, "utf-8"));
  } catch {
    return null;
  }
}

function writeTeamFile(cwd: string, entry: TeamEntry): void {
  const p = teamFilePath(cwd);
  try {
    mkdirSync(join(cwd, ".pi", "agent-sessions"), { recursive: true });
    writeFileSync(p, JSON.stringify(entry, null, 2), "utf-8");
  } catch {
    /* best-effort */
  }
}

// ── Presets de team ────────────────────────────────────────────────────────

interface Preset {
  id: string;
  label: string;
  roles: CortexRole[];
}

const PRESETS: Preset[] = [
  {
    id: "deep_full",
    label: "Deep Track full (designer + implementer + documenter)",
    roles: ["designer", "implementer", "documenter"],
  },
  {
    id: "deep_with_audit",
    label: "Deep Track + audit (designer + implementer + security + test-verifier + documenter)",
    roles: ["designer", "implementer", "security", "test-verifier", "documenter"],
  },
  {
    id: "design_pair",
    label: "Design pair (designer + implementer)",
    roles: ["designer", "implementer"],
  },
  {
    id: "audit_pair",
    label: "Audit pair (security + test-verifier)",
    roles: ["security", "test-verifier"],
  },
  {
    id: "explorer_only",
    label: "Explorer (análisis read-only)",
    roles: ["explorer"],
  },
  {
    id: "documenter_only",
    label: "Documenter observer (escuchar in-flight)",
    roles: ["documenter"],
  },
];

// ── Extension ──────────────────────────────────────────────────────────────

export default function (pi: ExtensionAPI) {
  /**
   * Abre el selector de presets y spawnea las terminales elegidas. Lo
   * llaman /cortex-team y el panel /cortex (vía
   * registerTeamActions). El cwd lo pasa el caller (cortexState.cwd ?? ctx.cwd).
   */
  async function openTeamSpawner(ctx: any, cwd: string): Promise<void> {
      // ── Guards ──
      if (!cwd) {
        ctx.ui.notify(
          "⬢ /cortex-team: no se pudo determinar el cwd. ¿Pi arrancó sin proyecto?",
          "warning"
        );
        return;
      }
      if (!cortexState.sessionId) {
        ctx.ui.notify(
          "⬢ /cortex-team: no hay Cortex Session activa. Tipeá tu tarea para que cortex-sync abra una.",
          "warning"
        );
        return;
      }
      // Diferenciar entre "no registrado en la red" y "registrado como worker".
      // Sólo el último es realmente un worker; el primero es un estado transitorio
      // donde cortex-net todavía no levantó el hub (típicamente porque el agent
      // activo es cortex-sync, que vive afuera de la red).
      if (!cortexState.myRole) {
        ctx.ui.notify(
          cortexState.activeAgentName === "cortex-sync"
            ? "⬢ /cortex-team: estás en cortex-sync (afuera de la red por diseño B'). " +
                "Cambiá a un agent del medio (/system → cortex-SDDwork) y volvé a intentar."
            : "⬢ /cortex-team: todavía no estás registrado en la red. Esperá unos " +
                "segundos a que cortex-net detecte el lock, o cambiá de agent con /system.",
          "warning"
        );
        return;
      }
      if (!cortexState.isMaster) {
        ctx.ui.notify(
          "⬢ /cortex-team: sólo el master (proceso que levantó el hub) puede " +
            "spawnear terminales. Vos sos worker — el spawn lo hace el master.",
          "warning"
        );
        return;
      }

      // ── Calcular qué presets tiene sentido mostrar ──
      const connected = new Set<CortexRole>(
        cortexState.peers.map((p) => p.role)
      );

      const labeledPresets = PRESETS.map((preset) => {
        const toOpen = preset.roles.filter((r) => !connected.has(r));
        const status =
          toOpen.length === 0
            ? "(todos ya conectados)"
            : toOpen.length === preset.roles.length
            ? `(abrir: ${toOpen.join(", ")})`
            : `(faltan: ${toOpen.join(", ")})`;
        return {
          preset,
          toOpen,
          label: `${preset.label}  ${status}`,
        };
      });

      // ── Selector ──
      const selected = await ctx.ui.select(
        "⬡ Cortex Team — Elegí qué roles abrir:",
        labeledPresets.map((p) => p.label)
      );
      if (selected === undefined) {
        ctx.ui.notify("Cancelado.", "info");
        return;
      }

      const choice = labeledPresets.find((p) => p.label === selected);
      if (!choice) return;
      if (choice.toOpen.length === 0) {
        ctx.ui.notify(
          "Todos los roles del preset ya están conectados. No hay nada que abrir.",
          "info"
        );
        return;
      }

      // ── Spawn ──
      ctx.ui.notify(
        `⬢ Spawneando ${choice.toOpen.length} terminal(es): ${choice.toOpen.join(", ")}…`,
        "info"
      );

      const results = choice.toOpen.map((role) => ({
        role,
        result: spawnTerminal(cwd, role),
      }));

      // ── Tracking en team.json ──
      const team: TeamEntry = readTeamFile(cwd) ?? {
        master_pid: process.pid,
        session_id: cortexState.sessionId,
        cwd: cwd,
        spawned: [],
      };
      for (const r of results) {
        if (r.result.success) {
          team.spawned.push({
            role: r.role,
            spawned_at: new Date().toISOString(),
            mechanism: r.result.mechanism ?? "unknown",
          });
        }
      }
      team.shutdown = false; // equipo recién (re)spawneado: vivo
      team.session_id = cortexState.sessionId ?? team.session_id; // refrescar
      writeTeamFile(cwd, team);

      // ── Reporte ──
      const ok = results.filter((r) => r.result.success);
      const failed = results.filter((r) => !r.result.success);

      if (ok.length > 0) {
        const mechanisms = [...new Set(ok.map((r) => r.result.mechanism))];
        ctx.ui.notify(
          `✓ Spawn ok: ${ok.map((r) => r.role).join(", ")} ` +
            `(via ${mechanisms.join(", ")}). ` +
            `Los peers van a aparecer en el cockpit cuando se conecten al hub.`,
          "success"
        );
      }

      if (failed.length > 0) {
        // Notas de diagnóstico (p.ej. el error REAL de wezterm cli).
        const notes = [...new Set(failed.map((r) => r.result.note).filter(Boolean))];
        // Fallback: armar bloque con todos los comandos y copiarlo.
        const block = failed
          .map(
            (r) =>
              `# ${r.role}\n${r.result.fallback ?? `Set-Location '${cwd}'; $env:CORTEX_NET_ROLE='${r.role}'; pi`}`
          )
          .join("\n\n");
        const copied = copyToClipboard(block);
        ctx.ui.notify(
          (notes.length ? notes.join("\n") + "\n\n" : "") +
            `⚠ No se pudieron abrir terminales para: ${failed
              .map((r) => r.role)
              .join(", ")}.\n` +
            (copied
              ? "Copié al clipboard el comando para abrir cada una a mano. " +
                "Pegalo en una pestaña/ventana nueva de tu terminal."
              : "Abrí esas terminales a mano y ejecutá:\n" + block),
          "warning"
        );
      }
  }

  pi.registerCommand("cortex-team", {
    description:
      "Spawnear terminales adicionales para los roles del medio (Pi 2.5+net multi-terminal)",
    async handler(_args: string, ctx: any) {
      await openTeamSpawner(ctx, cortexState.cwd ?? ctx.cwd ?? "");
    },
  });

  // Publicamos el spawner para que el panel /cortex lo dispare DE VERDAD.
  registerTeamActions({
    spawn: (ctx: any) => openTeamSpawner(ctx, cortexState.cwd ?? ctx.cwd ?? ""),
  });

  // ── /cortex-team-status ─ pequeño helper de debug ──────────────────
  pi.registerCommand("cortex-team-status", {
    description: "Mostrar el contenido actual de team.json (debug)",
    async handler(_args: string, ctx: any) {
      const cwd = cortexState.cwd ?? ctx.cwd ?? "";
      if (!cwd) {
        ctx.ui.notify("Sin cwd cacheado ni cwd en el contexto.", "warning");
        return;
      }
      const team = readTeamFile(cwd);
      if (!team) {
        ctx.ui.notify("No hay team.json todavía (nadie spawneó nada).", "info");
        return;
      }
      ctx.ui.notify(
        `master_pid=${team.master_pid} · session_id=${team.session_id.slice(0, 16)}… · ` +
          `spawned=[${team.spawned.map((s) => s.role).join(", ")}]`,
        "info"
      );
    },
  });

  // ── Coordinated shutdown (2c) ──────────────────────────────────────────
  // El master, al cerrar de verdad (reason "quit"), marca shutdown en
  // team.json. Los workers de la MISMA session_id lo detectan por polling y
  // AVISAN (no se auto-cierran: matar la terminal del usuario sería agresivo).
  let shutdownPoll: NodeJS.Timeout | null = null;
  let shutdownNotified = false;

  pi.on("session_start", async (_event, ctx) => {
    shutdownNotified = false;
    if (shutdownPoll) clearInterval(shutdownPoll);
    shutdownPoll = setInterval(() => {
      const cwd = cortexState.cwd;
      if (!cwd || shutdownNotified) return;
      // Solo nos importa si somos un worker registrado (el master no se avisa).
      if (cortexState.isMaster || !cortexState.myRole) return;
      const team = readTeamFile(cwd);
      if (team?.shutdown === true && team.session_id === cortexState.sessionId) {
        shutdownNotified = true;
        try {
          ctx.ui?.notify(
            "⬢ cortex-team: el master cerró la sesión. Esta terminal (worker) " +
              "quedó sin hub — podés cerrarla con Ctrl+D cuando quieras.",
            "warning"
          );
        } catch {
          /* best-effort */
        }
      }
    }, 6000);
  });

  pi.on("session_shutdown", async (event: any) => {
    if (shutdownPoll) {
      clearInterval(shutdownPoll);
      shutdownPoll = null;
    }
    // Solo el master, y solo en cierre real (quit), marca el shutdown del team.
    if (event?.reason !== "quit") return;
    if (!cortexState.isMaster) return;
    const cwd = cortexState.cwd;
    if (!cwd) return;
    const team = readTeamFile(cwd);
    if (!team) return;
    team.shutdown = true;
    team.shutdown_at = new Date().toISOString();
    writeTeamFile(cwd, team);
  });
}

files.project:.pi/extensions/cortex-tools.ts:
/**
 * cortex-tools — Cortex CLI como tools nativas de Pi
 *
 * Registra los comandos reales del CLI de Cortex v2.1 como tools nativas
 * de Pi. Los agentes pueden llamarlas igual que cualquier otra tool.
 *
 * Comandos reales verificados con `cortex --help`:
 *   search          → Query both memory layers
 *   remember        → Store a new episodic memory
 *   forget          → Delete an episodic memory by ID
 *   context         → Get enriched context for current work
 *   save-session    → Persist a structured session note into the vault
 *   create-spec     → Persist an implementation spec into the vault
 *   stats           → Print memory store statistics
 *   doctor          → Validate Cortex runtime prerequisites
 *   agent-guidelines→ Display agent behavior guidelines
 *   sync-vault      → Re-index the markdown vault
 *
 * Uso: pi -e .pi/extensions/cortex-tools.ts
 * Comando en Pi: /cortex-tools
 */

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { Text } from "@mariozechner/pi-tui";
import { Type } from "@sinclair/typebox";
import { existsSync } from "fs";
import { join } from "path";
import { homedir } from "os";
import { execFileSync, spawnSync } from "child_process";

// ── Resuelve el ejecutable de cortex ──────────────────────────────────────

function resolveCortexBin(): string {
  if (process.env.CORTEX_BIN && existsSync(process.env.CORTEX_BIN)) {
    return process.env.CORTEX_BIN;
  }

  const isWin = process.platform === "win32";
  const binName = isWin ? "cortex.exe" : "cortex";
  const scriptDir = isWin ? "Scripts" : "bin";
  const home = homedir();
  const candidates: string[] = [];

  // 1. pipx environment --value PIPX_LOCAL_VENVS (más confiable)
  try {
    const venvs = execFileSync("pipx", ["environment", "--value", "PIPX_LOCAL_VENVS"], {
      encoding: "utf-8", timeout: 5000,
    }).trim();
    if (venvs) {
      candidates.push(join(venvs, "cortex-memory", scriptDir, binName));
      candidates.push(join(venvs, "cortex", scriptDir, binName));
    }
  } catch {}

  // 2. Ruta derivada estándar de pipx en Windows (%USERPROFILE%\pipx\venvs)
  candidates.push(join(home, "pipx", "venvs", "cortex-memory", scriptDir, binName));
  candidates.push(join(home, "pipx", "venvs", "cortex", scriptDir, binName));

  if (isWin) {
    const localAppData = process.env.LOCALAPPDATA ?? join(home, "AppData", "Local");
    candidates.push(join(localAppData, "pipx", "pipx", "venvs", "cortex-memory", "Scripts", binName));
  } else {
    candidates.push(join(home, ".local", "pipx", "venvs", "cortex-memory", "bin", binName));
  }

  // 3. ~/.local/bin donde pipx instala los scripts globales
  candidates.push(join(home, ".local", "bin", binName));

  for (const c of candidates) {
    if (existsSync(c)) return c;
  }

  // 4. Fallback al PATH
  return binName;
}

// ── Runner ────────────────────────────────────────────────────────────────

function runCortex(
  bin: string,
  args: string[],
  cwd: string,
  configPath: string,
): { stdout: string; stderr: string; ok: boolean } {
  try {
    const result = spawnSync(bin, args, {
      cwd,
      encoding: "utf-8",
      timeout: 60_000,
      env: {
        ...process.env as Record<string, string>,
        CORTEX_CONFIG_PATH: configPath,
      },
    });
    return {
      stdout: result.stdout ?? "",
      stderr: result.stderr ?? "",
      ok: result.status === 0,
    };
  } catch (err: any) {
    return { stdout: "", stderr: err.message, ok: false };
  }
}

function fmt(stdout: string, stderr: string, ok: boolean): string {
  const out = stdout.trim();
  const err = stderr.trim();
  if (out) return out;
  if (!ok && err) return `Error: ${err}`;
  return ok ? "(completado sin output)" : `Falló: ${err || "sin detalles"}`;
}

// ── Extension ──────────────────────────────────────────────────────────────

export default function (pi: ExtensionAPI) {
  let bin = "";
  let cwd = "";
  let cfg = "";

  pi.registerMessageRenderer("cortex-tools", (message, _options, theme) => {
    const content = typeof message.content === "string" ? message.content : "";
    return new Text(theme.fg("cyan", "⬡ cortex: ") + content, 0, 0);
  });

  pi.on("session_start", async (_event, ctx) => {
    cwd = ctx.cwd;
    cfg = join(cwd, "config.yaml");
    bin = resolveCortexBin();

    const check = spawnSync(bin, ["--version"], {
      encoding: "utf-8", timeout: 5000,
      env: { ...process.env as Record<string, string> },
    });

    if (check.status === 0 || (check.stderr ?? "").includes("cortex")) {
      const ver = ((check.stdout ?? "") + (check.stderr ?? "")).trim().split("\n")[0];
      ctx.ui.notify(`✓ Cortex CLI: ${ver || "OK"} — tools cortex_* disponibles`, "success");
    } else {
      ctx.ui.notify(`⚠ Cortex CLI no encontrado (${bin}) — corré /cortex-tools para diagnosticar`, "warning");
    }
  });

  // ── cortex_search ────────────────────────────────────────────────────────
  pi.registerTool({
    name: "cortex_search",
    label: "Cortex: Buscar memoria",
    description: "Busca en la memoria híbrida de Cortex (episódica + semántica). Recupera contexto relevante antes de implementar.",
    parameters: Type.Object({
      query: Type.String({ description: "Consulta en lenguaje natural" }),
      limit: Type.Optional(Type.Number({ description: "Máximo de resultados (default: 10)" })),
    }),
    async execute(_id, params) {
      const args = ["search", params.query];
      if (params.limit) args.push("--limit", String(params.limit));
      const r = runCortex(bin, args, cwd, cfg);
      return { content: [{ type: "text" as const, text: fmt(r.stdout, r.stderr, r.ok) }] };
    },
  });

  // ── cortex_context ───────────────────────────────────────────────────────
  pi.registerTool({
    name: "cortex_context",
    label: "Cortex: Contexto enriquecido",
    description: "Obtiene contexto enriquecido para el trabajo actual. Equivale al pre-flight de cortex-sync.",
    parameters: Type.Object({
      ticket: Type.Optional(Type.String({ description: "ID o descripción del ticket actual" })),
    }),
    async execute(_id, params) {
      const args = ["context"];
      if (params.ticket) args.push("--ticket", params.ticket);
      const r = runCortex(bin, args, cwd, cfg);
      return { content: [{ type: "text" as const, text: fmt(r.stdout, r.stderr, r.ok) }] };
    },
  });

  // ── cortex_remember ──────────────────────────────────────────────────────
  pi.registerTool({
    name: "cortex_remember",
    label: "Cortex: Guardar memoria episódica",
    description: "Guarda una decisión, aprendizaje o contexto importante en la memoria episódica de Cortex.",
    parameters: Type.Object({
      content: Type.String({ description: "Contenido a guardar en memoria" }),
    }),
    async execute(_id, params) {
      const r = runCortex(bin, ["remember", params.content], cwd, cfg);
      return { content: [{ type: "text" as const, text: fmt(r.stdout, r.stderr, r.ok) }] };
    },
  });

  // ── cortex_save_session ──────────────────────────────────────────────────
  pi.registerTool({
    name: "cortex_save_session",
    label: "Cortex: Guardar sesión",
    description: "Persiste una nota estructurada de la sesión en el vault. Usar al finalizar una sesión de trabajo.",
    parameters: Type.Object({
      content: Type.String({ description: "Resumen estructurado de la sesión en Markdown" }),
    }),
    async execute(_id, params) {
      const r = runCortex(bin, ["save-session", params.content], cwd, cfg);
      return { content: [{ type: "text" as const, text: fmt(r.stdout, r.stderr, r.ok) }] };
    },
  });

  // ── cortex_create_spec ───────────────────────────────────────────────────
  pi.registerTool({
    name: "cortex_create_spec",
    label: "Cortex: Crear spec",
    description: "Persiste una especificación técnica en el vault. Usado por cortex-sync al finalizar el pre-flight.",
    parameters: Type.Object({
      content: Type.String({ description: "Contenido completo de la spec en Markdown" }),
    }),
    async execute(_id, params) {
      const r = runCortex(bin, ["create-spec", params.content], cwd, cfg);
      return { content: [{ type: "text" as const, text: fmt(r.stdout, r.stderr, r.ok) }] };
    },
  });

  // ── cortex_forget ────────────────────────────────────────────────────────
  pi.registerTool({
    name: "cortex_forget",
    label: "Cortex: Olvidar memoria",
    description: "Elimina una memoria episódica por su ID.",
    parameters: Type.Object({
      id: Type.String({ description: "ID de la memoria a eliminar" }),
    }),
    async execute(_id, params) {
      const r = runCortex(bin, ["forget", params.id], cwd, cfg);
      return { content: [{ type: "text" as const, text: fmt(r.stdout, r.stderr, r.ok) }] };
    },
  });

  // ── cortex_stats ─────────────────────────────────────────────────────────
  pi.registerTool({
    name: "cortex_stats",
    label: "Cortex: Estadísticas de memoria",
    description: "Muestra estadísticas del almacén de memoria de Cortex.",
    parameters: Type.Object({}),
    async execute(_id) {
      const r = runCortex(bin, ["stats"], cwd, cfg);
      return { content: [{ type: "text" as const, text: fmt(r.stdout, r.stderr, r.ok) }] };
    },
  });

  // ── cortex_doctor ────────────────────────────────────────────────────────
  pi.registerTool({
    name: "cortex_doctor",
    label: "Cortex: Diagnóstico del sistema",
    description: "Valida los prerequisitos de runtime y el estado de governance de Cortex.",
    parameters: Type.Object({}),
    async execute(_id) {
      const r = runCortex(bin, ["doctor"], cwd, cfg);
      return { content: [{ type: "text" as const, text: fmt(r.stdout, r.stderr, r.ok) }] };
    },
  });

  // ── cortex_agent_guidelines ──────────────────────────────────────────────
  pi.registerTool({
    name: "cortex_agent_guidelines",
    label: "Cortex: Guías del agente",
    description: "Muestra las guías de comportamiento del agente Cortex para el proyecto actual.",
    parameters: Type.Object({}),
    async execute(_id) {
      const r = runCortex(bin, ["agent-guidelines"], cwd, cfg);
      return { content: [{ type: "text" as const, text: fmt(r.stdout, r.stderr, r.ok) }] };
    },
  });

  // ── cortex_sync_vault ────────────────────────────────────────────────────
  pi.registerTool({
    name: "cortex_sync_vault",
    label: "Cortex: Sincronizar vault",
    description: "Re-indexa el vault de Markdown en la memoria semántica de Cortex.",
    parameters: Type.Object({}),
    async execute(_id) {
      const r = runCortex(bin, ["sync-vault"], cwd, cfg);
      return { content: [{ type: "text" as const, text: fmt(r.stdout, r.stderr, r.ok) }] };
    },
  });

  // ── /cortex-tools ────────────────────────────────────────────────────────
  pi.registerCommand("cortex-tools", {
    description: "Lista las tools de Cortex y verifica el CLI",
    handler(_args, ctx) {
      const check = spawnSync(bin, ["--version"], {
        encoding: "utf-8", timeout: 5000,
        env: { ...process.env as Record<string, string> },
      });
      const ver = ((check.stdout ?? "") + (check.stderr ?? "")).trim().split("\n")[0] || "desconocida";
      const status = check.status === 0 ? "✓ OK" : "✗ NO DISPONIBLE";

      pi.sendMessage({
        customType: "cortex-tools",
        content: [
          `Cortex CLI: ${bin}`,
          `Estado: ${status}  Versión: ${ver}`,
          `Config: ${cfg}`,
          "",
          "Tools disponibles:",
          "  cortex_search           — buscar en memoria híbrida",
          "  cortex_context          — contexto enriquecido (pre-flight)",
          "  cortex_remember         — guardar memoria episódica",
          "  cortex_save_session     — persistir sesión en vault",
          "  cortex_create_spec      — crear spec en vault",
          "  cortex_forget           — eliminar memoria por ID",
          "  cortex_stats            — estadísticas de memoria",
          "  cortex_doctor           — diagnóstico del sistema",
          "  cortex_agent_guidelines — guías del agente",
          "  cortex_sync_vault       — re-indexar vault",
        ].join("\n"),
        display: true,
      });
    },
  });
}

files.project:.pi/extensions/damage-control.ts:
/**
 * damage-control — Cortex Safety Auditor en tiempo real
 *
 * Intercepta cada llamada a bash y la evalúa contra las reglas definidas
 * en .pi/damage-control-rules.yaml antes de ejecutarla.
 *
 * Reglas que aplica:
 *   bashToolPatterns   → bloquea o pide confirmación en comandos peligrosos
 *   zeroAccessPaths    → bloquea acceso total a archivos sensibles (.env, .ssh, *.pem)
 *   readOnlyPaths      → permite leer, bloquea escritura en lockfiles y /etc/
 *   noDeletePaths      → bloquea borrado de .git/, README.md, Dockerfiles
 *
 * Además: protege los archivos críticos del vault de Cortex.
 *
 * Uso: pi -e .pi/extensions/damage-control.ts
 *
 * Basado en disler/pi-vs-claude-code damage-control.ts, adaptado para Cortex.
 */

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { Text } from "@mariozechner/pi-tui";
import { readFileSync, existsSync } from "fs";
import { join } from "path";

// ── Types ──────────────────────────────────────────────────────────────────

interface BashPattern {
  pattern: string;
  reason: string;
  ask?: boolean;  // true = pide confirmación en vez de bloquear directamente
}

interface DamageControlRules {
  bashToolPatterns?: BashPattern[];
  zeroAccessPaths?: string[];
  readOnlyPaths?: string[];
  noDeletePaths?: string[];
}

// ── YAML parser mínimo para las reglas ────────────────────────────────────

function parseRulesYaml(raw: string): DamageControlRules {
  const rules: DamageControlRules = {
    bashToolPatterns: [],
    zeroAccessPaths: [],
    readOnlyPaths: [],
    noDeletePaths: [],
  };

  const lines = raw.split("\n");
  let section: keyof DamageControlRules | null = null;
  let currentPattern: BashPattern | null = null;

  for (const line of lines) {
    if (line.startsWith("#") || line.trim() === "") continue;

    // Sección principal
    const sectionMatch = line.match(/^(\w[\w-]*):\s*$/);
    if (sectionMatch) {
      if (currentPattern && section === "bashToolPatterns") {
        rules.bashToolPatterns!.push(currentPattern);
        currentPattern = null;
      }
      section = sectionMatch[1] as keyof DamageControlRules;
      continue;
    }

    if (!section) continue;

    // Lista simple de strings (zeroAccessPaths, readOnlyPaths, noDeletePaths)
    if (section !== "bashToolPatterns") {
      const itemMatch = line.match(/^\s+-\s+"?([^"]+)"?\s*$/);
      if (itemMatch) {
        (rules[section] as string[]).push(itemMatch[1].trim());
      }
      continue;
    }

    // bashToolPatterns: cada item tiene pattern, reason, ask?
    const listItem = line.match(/^\s+-\s+pattern:\s+"?([^"]+)"?\s*$/);
    if (listItem) {
      if (currentPattern) rules.bashToolPatterns!.push(currentPattern);
      currentPattern = { pattern: listItem[1], reason: "" };
      continue;
    }
    const reasonMatch = line.match(/^\s+reason:\s+"?([^"]+)"?\s*$/);
    if (reasonMatch && currentPattern) {
      currentPattern.reason = reasonMatch[1];
      continue;
    }
    const askMatch = line.match(/^\s+ask:\s+(true|false)\s*$/);
    if (askMatch && currentPattern) {
      currentPattern.ask = askMatch[1] === "true";
    }
  }
  if (currentPattern && section === "bashToolPatterns") {
    rules.bashToolPatterns!.push(currentPattern);
  }

  return rules;
}

// ── Reglas por defecto de Cortex (si no existe el YAML) ───────────────────

const DEFAULT_RULES: DamageControlRules = {
  bashToolPatterns: [
    { pattern: "rm\\s+(-rf?|--recursive)", reason: "rm -rf puede borrar datos irreversiblemente", ask: true },
    { pattern: "git\\s+reset\\s+--hard", reason: "git reset --hard descarta cambios no commiteados", ask: true },
    { pattern: "git\\s+push\\s+.*--force", reason: "force push puede sobrescribir historia del repositorio", ask: true },
    { pattern: "DROP\\s+(?:TABLE|DATABASE|SCHEMA)", reason: "Operación destructiva de base de datos", ask: false },
    { pattern: "truncate\\s+table", reason: "Borra todos los datos de la tabla", ask: true },
    { pattern: "aws\\s+s3\\s+rm\\s+.*--recursive", reason: "Borrado masivo en S3", ask: false },
    { pattern: "\\bsudo\\s+rm\\b", reason: "rm con sudo es extremadamente peligroso", ask: false },
  ],
  zeroAccessPaths: [".env", ".env.local", ".env.production", "~/.ssh/", "*.pem", "*.key", "secrets.yaml"],
  readOnlyPaths: ["package-lock.json", "bun.lock", "poetry.lock", "/etc/"],
  noDeletePaths: [".git/", "README.md", "Dockerfile", "docker-compose.yml", ".pi/agents/", ".pi/skills/"],
};

// ── Helpers ────────────────────────────────────────────────────────────────

function matchesPath(command: string, patterns: string[]): string | null {
  for (const p of patterns) {
    const escaped = p.replace(/[.+^${}()|[\]\\]/g, "\\$&").replace(/\*/g, ".*");
    if (new RegExp(escaped, "i").test(command)) return p;
  }
  return null;
}

function isDestructiveWrite(command: string, paths: string[]): boolean {
  const writeOps = /\b(echo\s+.*>|tee|cp|mv|rm|write|sed\s+-i)\b/i;
  if (!writeOps.test(command)) return false;
  return matchesPath(command, paths) !== null;
}

function isDeleteOp(command: string, paths: string[]): boolean {
  const delOps = /\b(rm|git\s+clean|rmdir)\b/i;
  if (!delOps.test(command)) return false;
  return matchesPath(command, paths) !== null;
}

// ── Extension ──────────────────────────────────────────────────────────────

export default function (pi: ExtensionAPI) {
  pi.registerMessageRenderer("cortex-damage-control", (message, _options, theme) => {
    const content = typeof message.content === "string" ? message.content : "";
    return new Text(theme.fg("warning", "🛡 ") + content, 0, 0);
  });

  let rules: DamageControlRules = DEFAULT_RULES;
  let blockedCount = 0;
  let askedCount = 0;

  function loadRules(cwd: string) {
    const rulesPath = join(cwd, ".pi", "damage-control-rules.yaml");
    if (existsSync(rulesPath)) {
      try {
        rules = parseRulesYaml(readFileSync(rulesPath, "utf-8"));
      } catch {
        rules = DEFAULT_RULES;
      }
    }
  }

  pi.on("session_start", (_event: any, ctx: any) => {
    loadRules(process.cwd());
    ctx.ui.notify("🛡 Cortex damage-control activo", "info");
  });

  // ── Intercepta cada tool_call ──
  pi.on("tool_call", async (event: any, ctx: any) => {
    if (event.toolName !== "bash") return;

    const command: string = event.input?.command || "";
    if (!command.trim()) return;

    // 1. Rutas de acceso cero
    const zeroMatch = matchesPath(command, rules.zeroAccessPaths || []);
    if (zeroMatch) {
      blockedCount++;
      ctx.ui.notify(`🛡 BLOQUEADO: acceso a "${zeroMatch}" prohibido`, "error");
      return { block: true, reason: `Acceso a "${zeroMatch}" bloqueado por damage-control (zeroAccessPaths)` };
    }

    // 2. Rutas de solo lectura (bloquea escritura)
    if (isDestructiveWrite(command, rules.readOnlyPaths || [])) {
      blockedCount++;
      ctx.ui.notify("🛡 BLOQUEADO: intento de escritura en ruta de solo lectura", "error");
      return { block: true, reason: "Escritura en readOnlyPath bloqueada por damage-control" };
    }

    // 3. Rutas sin borrado
    if (isDeleteOp(command, rules.noDeletePaths || [])) {
      blockedCount++;
      ctx.ui.notify("🛡 BLOQUEADO: intento de borrar archivo/directorio protegido", "error");
      return { block: true, reason: "Borrado de noDeletePath bloqueado por damage-control" };
    }

    // 4. Patrones de bash peligrosos
    for (const rule of rules.bashToolPatterns || []) {
      if (!new RegExp(rule.pattern, "i").test(command)) continue;

      if (!rule.ask) {
        blockedCount++;
        ctx.ui.notify(`🛡 BLOQUEADO: ${rule.reason}`, "error");
        return { block: true, reason: rule.reason };
      }

      // Pide confirmación interactiva
      if (!ctx.hasUI) {
        blockedCount++;
        return { block: true, reason: `${rule.reason} (sin UI para confirmar)` };
      }

      askedCount++;
      // ctx.ui.confirm(title: string, message: string) → Promise<boolean>
      const confirmed: boolean = await ctx.ui.confirm(
        "⚠ Cortex Damage Control",
        `Comando peligroso detectado:\n\`${command}\`\n\nMotivo: ${rule.reason}\n\n¿Continuar de todas formas?`
      );

      if (!confirmed) {
        blockedCount++;
        return { block: true, reason: `Usuario canceló: ${rule.reason}` };
      }
      // Si confirmó, deja pasar
    }
  });

  // ── /damage-stats: muestra estadísticas de la sesión ──
  pi.registerCommand("damage-stats", {
    description: "Muestra estadísticas del damage-control en esta sesión",
    handler(_args: string, _ctx: any) {
      pi.sendMessage({
        customType: "cortex-damage-control",
        content:
          `Cortex Damage Control — Estadísticas\n\n` +
          `Comandos bloqueados: ${blockedCount}\n` +
          `Confirmaciones pedidas: ${askedCount}\n` +
          `Patrones activos: ${rules.bashToolPatterns?.length ?? 0}\n` +
          `Rutas protegidas: ${(rules.zeroAccessPaths?.length ?? 0) + (rules.readOnlyPaths?.length ?? 0) + (rules.noDeletePaths?.length ?? 0)}`,
        display: true,
      });
    },
  });
}

